// Üretilen dosya: tool/ozgun/uret.py. Tarih · Avrupa tarihi: Rönesans, Reform, Coğrafi Keşifler, mutlakiyet (kolay).
const ozHistory7Kolay = <(String, String, List<String>, String)>[
  ('İtalyan kent devletlerinin savaşlarını çoğu zaman sözleşmeyle tutulan paralı ordu komutanlarına yaptırması bu komutanlara verilen hangi adla anılır?', 'Condottiere', ['Kondotta', 'Gonfaloniere', 'Kapitan'], 'Condottiere, kent devletleriyle sözleşme (condotta) imzalayan paralı asker önderidir; Sforza ve Colleoni bunların en ünlülerindendir.'),
  ('Floransa\'nın 1252\'den itibaren bastığı ve Avrupa ticaretinde güvenilir bir ödeme aracına dönüşen altın para hangisidir?', 'Florin', ['Duka', 'Lira', 'Gulden'], 'Floransa\'nın florini sabit ayarı sayesinde uluslararası ticarette güven kazandı; bu durum kentin bankacılık gücünü yansıtır.'),
  ('Floransa\'da resmî olarak hiçbir yüksek makamı uzun süre üstlenmeden kentin fiilî yöneticisi olan ve ölümünden sonra \'Pater Patriae\' (Vatanın Babası) diye anılan Medici kimdir?', 'Cosimo de\' Medici', ['Lorenzo de\' Medici', 'Giovanni di Bicci de\' Medici', 'Piero de\' Medici'], 'Yaşlı Cosimo, banka servetini ve himaye ağını kullanarak cumhuriyet kurumlarını perde arkasından yönetti; ölümünden sonra bu unvanla onurlandırıldı.'),
  ('Cicero\'nun Atticus\'a yazdığı mektupları 1345\'te Verona\'da bulan ve Laura\'ya yazdığı İtalyanca sonelerle tanınan hümanist kimdir?', 'Francesco Petrarca', ['Giovanni Boccaccio', 'Coluccio Salutati', 'Leonardo Bruni'], 'Petrarca, kayıp antik metinleri arama geleneğinin öncüsüdür; Canzoniere\'deki Laura şiirleri sone türünü Avrupa\'ya yaydı. Bu yüzden \'hümanizmin babası\' sayılır.'),
  ('Floransa Katedrali\'nin (Santa Maria del Fiore) dev kubbesini, iç içe iki kabuk ve balıksırtı tuğla örgüsüyle yerden iskele kurmadan tamamlayan mimar kimdir?', 'Filippo Brunelleschi', ['Leon Battista Alberti', 'Michelozzo di Bartolomeo', 'Donato Bramante'], 'Brunelleschi\'nin kubbesi 1436\'da tamamlandı; dönemin en büyük mühendislik başarılarından biri sayılır.'),
  ('Erken Rönesans sanatçıları ile Orta Çağ (Gotik) ressamları karşılaştırıldığında Rönesans resminin belirgin yeniliği hangisidir?', 'Gerçekçi mekân ve hacim duygusu yaratmak için perspektif ve ışık-gölge kullanması', ['Figürleri önem sırasına göre farklı büyüklükte çizmesi', 'Altın yaldızlı düz arka planı yaygınlaştırması', 'Dinî konuları tümüyle bırakıp yalnız manzara ve gündelik yaşam sahneleri resmetmesi'], 'Rönesans ressamları, izleyiciye pencereden bakıyormuş gibi bir derinlik sunmak için matematiksel perspektif ve modelaj kullandı.'),
  ('Kendisi de şiirler yazan, Floransa\'yı 1469\'dan 1492\'deki ölümüne dek perde arkasından yöneten ve \'Muhteşem\' lakabıyla anılan Medici kimdir?', 'Lorenzo de\' Medici', ['Cosimo de\' Medici', 'Giuliano de\' Medici', 'Piero di Lorenzo de\' Medici'], 'Lorenzo il Magnifico; Botticelli, Ghirlandaio ve genç Michelangelo gibi sanatçıları himaye etti. Ölümü İtalyan dengesinin bozulduğu döneme denk gelir.'),
  ('Deniz kabuğu üzerinde kıyıya yaklaşan bir tanrıçayı tasvir eden ve antik mitolojiyi büyük ölçekli bir tabloya taşıyan ünlü Floransa eseri hangisidir?', 'Botticelli\'nin \'Venüs\'ün Doğuşu\'', ['Tiziano\'nun \'Urbino Venüsü\'', 'Giorgione\'nin \'Uyuyan Venüs\'ü', 'Raffaello\'nun \'Galatea\'sı'], 'Botticelli\'nin 1480\'lerdeki eseri, Hristiyan konuların egemen olduğu bir dönemde pagan mitolojisinin büyük bir tabloya konu edilmesiyle dikkat çeker.'),
  ('1490\'larda Floransa\'da vaazlarıyla halkı etkileyen, lüksü ve sanat eserlerini günah sayıp \'kibirlerin yakılması\' törenleri düzenleten Dominiken rahip kimdir?', 'Girolamo Savonarola', ['Bernardino da Siena', 'Antonino Pierozzi', 'Ignatius de Loyola'], 'Savonarola 1497\'de aynalar, kitaplar, tablolar gibi \'kibir\' nesnelerini meydanda yaktırdı; bir süre kentin fiilî ahlak önderi oldu.'),
  ('Lorenzo de\' Medici\'nin oğlu olup papa seçildiğinde Roma\'daki Aziz Petrus Bazilikası\'nın yapımı için endüljans satışını genişleten papa hangisidir?', 'X. Leo', ['II. Julius', 'VII. Clemens', 'VI. Alexander'], 'Giovanni de\' Medici 1513\'te X. Leo adıyla papa oldu; onun döneminde yürütülen endüljans kampanyası Luther\'in tepkisini tetikledi.'),
  ('Leonardo da Vinci\'nin \'Son Akşam Yemeği\' eseri hangi kentteki Santa Maria delle Grazie manastırının yemekhanesinde bulunur?', 'Milano', ['Floransa', 'Venedik', 'Roma'], 'Eser, Ludovico Sforza döneminde, 1490\'ların ortasında Milano\'daki Dominiken manastırının yemekhane duvarına yapıldı.'),
  ('Leonardo\'nun resimlerinde konturları keskin çizgiler yerine dumanlı, yumuşak geçişlerle eritme tekniğine ne ad verilir?', 'Sfumato', ['Chiaroscuro', 'Tenebrizm', 'Trompe-l\'œil'], 'Sfumato İtalyanca \'duman gibi\' anlamına gelir; Mona Lisa\'nın yüz ve manzarasında bu yumuşak geçişler açıkça görülür.'),
  ('Bir çember ve kare içine yerleştirilmiş kollarını açmış bir erkek figürüyle insan vücudunun oranlarını gösteren ünlü Leonardo çizimi hangi antik yazarın kuramına dayanır?', 'Vitruvius', ['Ptolemaios', 'Galenos', 'Plinius'], 'Roma mimarı Vitruvius, ideal insan bedeninin daire ve kareye yerleşebileceğini yazmıştı; Leonardo bu düşünceyi ölçülü bir çizimle görselleştirdi.'),
  ('Leonardo\'nun bitkiler, kuşların uçuşu, su akıntıları ve insan anatomisi üzerine binlerce sayfa not tutması Rönesans\'taki hangi yaklaşımın örneğidir?', 'Doğayı doğrudan gözleme dayalı olarak incelemek', ['Bilgiyi yalnız antik otoritelerden almak', 'Doğayı yalnız kutsal metinlerle açıklamak', 'Sanatı bilimden kesin çizgilerle ayırmak'], 'Leonardo, \'deneyim bütün kesinliğin anasıdır\' anlayışıyla çizim ve gözlemi bilgi edinme aracı olarak kullandı.'),
  ('Michelangelo\'nun Roma\'daki Aziz Petrus Bazilikası\'nda bulunan ve üzerinde imzası taşıyan tek eseri olarak bilinen heykel hangisidir?', 'Pietà', ['Musa', 'Bacchus', 'Kurtarıcı İsa'], 'Genç Michelangelo\'nun 1498-1499\'da yaptığı Pietà\'da, Meryem\'in göğsünden geçen kuşağa adını kazıdığı bilinir.'),
  ('Michelangelo, Sistina Şapeli\'nin tavan fresklerini hangi papanın siparişiyle 1508-1512 yılları arasında yapmıştır?', 'II. Julius', ['X. Leo', 'III. Paulus', 'VI. Alexander'], 'Kendini daha çok heykeltıraş sayan Michelangelo bu işi isteksizce kabul etti; tavan freskleri yaklaşık dört yılda tamamlandı.'),
  ('Michelangelo ileri yaşında Aziz Petrus Bazilikası\'nın baş mimarı olunca projeye en çok hangi öğesiyle damgasını vurmuştur?', 'Bazilikanın büyük kubbesinin tasarımıyla', ['Bazilikanın önündeki sütunlu meydanla', 'Bronz baldaken ile', 'Ön cephenin çan kuleleriyle'], 'Michelangelo kubbeyi tasarladı; kubbe onun ölümünden sonra Giacomo della Porta tarafından tamamlandı. Meydan ve baldaken ise Bernini\'nin eseridir.'),
  ('Michelangelo\'nun Sistina tavanındaki sahneler arasında Tanrı ile Adem\'in parmaklarının neredeyse birbirine değdiği bölüm hangisidir?', 'Adem\'in Yaratılışı', ['Cennetten Kovuluş', 'Nuh Tufanı', 'Işığın Karanlıktan Ayrılması'], 'Adem\'in Yaratılışı, Tekvin kitabından alınan dokuz sahneden biridir ve Rönesans sanatının en tanınmış görüntülerindendir.'),
  ('Vatikan\'daki Stanza della Segnatura duvarında Platon ile Aristoteles\'in antik düşünürler arasında merkezde yürüdüğü freski yapan ressam kimdir?', 'Raffaello Sanzio', ['Pietro Perugino', 'Andrea Mantegna', 'Domenico Ghirlandaio'], 'Raffaello\'nun \'Atina Okulu\', II. Julius için Vatikan odalarına yapılan fresklerden biridir ve klasik bilgeliğin Rönesans\'taki itibarını yansıtır.'),
  ('Raffaello 1520\'de 37 yaşında öldüğünde, isteği üzerine Roma\'daki hangi antik yapıya gömülmüştür?', 'Pantheon', ['Kolezyum', 'Castel Sant\'Angelo', 'Caracalla Hamamları'], 'Raffaello\'nun mezarı, bir kiliseye dönüştürülmüş antik tapınak olan Pantheon\'dadır; bu tercih antikiteye duyduğu hayranlığı yansıtır.'),
  ('Zırh giyip ordularının başında bizzat sefere çıkmasıyla \'savaşçı papa\' diye anılan, aynı zamanda Michelangelo ve Raffaello\'nun büyük hamisi olan papa kimdir?', 'II. Julius', ['VI. Alexander', 'X. Leo', 'VII. Clemens'], 'II. Julius (1503-1513), papalık devletinin topraklarını geri almak için savaşlar yürüttü ve Roma\'yı büyük sanat projeleriyle donattı.'),
  ('Vatikan\'ın bugün de görevde olan muhafız birliği hangi ülkeden askerlerden oluşturulmuştur?', 'İsviçre', ['İspanya', 'Avusturya', 'Fransa'], 'II. Julius 1506\'da İsviçreli paralı askerlerden oluşan bir muhafız birliği kurdu; İsviçreliler dönemin en saygın piyadeleri sayılıyordu.'),
  ('Sistina Şapeli adını hangi papadan almıştır?', 'IV. Sixtus', ['V. Sixtus', 'II. Julius', 'IV. Paulus'], 'Şapel, 1470\'lerin sonunda IV. Sixtus tarafından yaptırıldı; yan duvarlarındaki fresklerde Botticelli, Perugino ve Ghirlandaio çalıştı.'),
  ('İmparator V. Karl\'ın saray ressamı olarak onu 1547 Mühlberg zaferinden sonra zırhlı ve at üstünde resmeden, Venedik okulunun en ünlü ustası kimdir?', 'Tiziano', ['Paolo Veronese', 'Jacopo Tintoretto', 'Giovanni Bellini'], 'Tiziano, V. Karl ve oğlu II. Felipe için çok sayıda portre ve mitolojik tablo yaptı; imparator ona soyluluk unvanı verdi.'),
  ('1550\'de yayımladığı biyografi derlemesiyle Cimabue\'den Michelangelo\'ya kadar İtalyan sanatçıların hayatlarını anlatan ve sanat tarihinin kurucusu sayılan yazar kimdir?', 'Giorgio Vasari', ['Benvenuto Cellini', 'Baldassare Castiglione', 'Cennino Cennini'], 'Vasari\'nin \'Hayatlar\' adlı eseri, sanatın Giotto\'dan Michelangelo\'ya doğru ilerleyen bir \'yeniden doğuş\' olduğu anlatısını kurdu.'),
  ('Gent Kilisesi için kardeşiyle birlikte yaptığı büyük sunak panosu ve 1434 tarihli bir çift portresindeki ayrıntılı yansıtıcı aynasıyla tanınan Flaman ressam kimdir?', 'Jan van Eyck', ['Rogier van der Weyden', 'Hans Memling', 'Robert Campin'], 'Jan van Eyck, yağlı boyayı ince katmanlar hâlinde kullanarak görülmemiş bir ayrıntı ve parlaklık elde etti; Arnolfini Portresi bunun en ünlü örneğidir.'),
  ('Cennet, dünyevi hazlar ve cehennemi gösteren üç bölümlü, garip yaratıklarla dolu \'Dünyevi Zevkler Bahçesi\' adlı eserin ressamı kimdir?', 'Hieronymus Bosch', ['Pieter Bruegel', 'Matthias Grünewald', 'Quentin Matsys'], 'Bosch\'un fantastik ve ahlaki uyarılar içeren dünyası, Felemenk sanatında eşsiz bir yer tutar; eser bugün Madrid\'deki Prado\'dadır.'),
  ('Bir köyde kış manzarasını, karlı tepeden yorgun dönen avcıları ve buz üzerinde kayan köylüleri gösteren 1565 tarihli ünlü Flaman tablonun ressamı kimdir?', 'Yaşlı Pieter Bruegel', ['Jan van Eyck', 'Hans Memling', 'Lucas van Leyden'], 'Bruegel, mevsimler dizisinin bir parçası olan \'Karda Avcılar\'da gündelik köylü yaşamını anıtsal bir manzara içinde ele aldı.'),
  ('İngiliz sarayında çalışan Hans Holbein\'ın \'Elçiler\' (1533) tablosunda iki diplomatın ayaklarının dibinde yandan bakıldığında seçilebilen çarpık nesne nedir?', 'Bir insan kafatası', ['Bir dünya küresi', 'Bir kum saati', 'Bir kılıç'], 'Anamorfik olarak çizilen kafatası, dünyevi bilgi ve zenginliğin ölüm karşısındaki geçiciliğini hatırlatan bir vanitas simgesidir.'),
  ('Delilik tanrıçasının ağzından keşişleri, ilahiyatçıları ve papaları alaya alan 1511 tarihli \'Deliliğe Övgü\' adlı hicvin yazarı kimdir?', 'Rotterdamlı Erasmus', ['Thomas More', 'François Rabelais', 'Ulrich von Hutten'], 'Erasmus bu eseri dostu Thomas More\'un evinde kaleme aldı ve ona ithaf etti; kilisedeki yozlaşmayı mizahla eleştirdi.'),
  ('Özel mülkiyetin bulunmadığı, herkesin altı saat çalıştığı ve dinî hoşgörünün geçerli olduğu hayalî bir adayı anlatan 1516 tarihli eserin yazarı kimdir?', 'Thomas More', ['Francis Bacon', 'Tommaso Campanella', 'Erasmus'], 'Thomas More\'un \'Ütopya\'sı, adanın düzeni üzerinden dönemin İngiltere\'sindeki eşitsizlikleri ve çitleme gibi uygulamaları eleştirir.'),
  ('Thomas More\'un 1535\'te idam edilmesinin nedeni hangisidir?', 'Kralı İngiltere Kilisesi\'nin başı olarak tanıyan yemini etmeyi reddetmesi', ['Ütopya kitabında krala açıkça hakaret ettiği için vatan hainliğiyle suçlanması', 'İspanya ile gizli bir ittifak kurarak İngiltere\'ye karşı savaş hazırlaması', 'Protestan görüşleri benimseyip papaya karşı ayaklanma başlatması'], 'Lord Chancellor olarak görev yapmış More, VIII. Henry\'nin kilise üzerindeki üstünlüğünü kabul etmedi ve vatana ihanetten idam edildi.'),
  ('Bordeaux yakınlarındaki şatosunun kulesine çekilerek \'Ne biliyorum?\' sorusunu kendine düstur edinen ve kişisel deneyimlerinden yola çıkan bir edebiyat türünü başlatan Fransız yazar kimdir?', 'Michel de Montaigne', ['François Rabelais', 'Pierre de Ronsard', 'Étienne de La Boétie'], 'Montaigne\'in 1580\'de yayımlanan \'Denemeler\'i, deneme türüne adını verdi; şüpheci ve hoşgörülü bir insan anlayışı yansıtır.'),
  ('Johannes Gutenberg\'in matbaasını kurduğu ve 1450\'lerde ilk büyük basılı kitabı ürettiği Alman kenti hangisidir?', 'Mainz', ['Nürnberg', 'Strasbourg', 'Köln'], 'Gutenberg Mainz\'da çalıştı; Strasbourg\'da da bir süre deneyler yaptığı bilinir. İlk büyük eseri olan İncil 1455 dolaylarında tamamlandı.'),
  ('Gutenberg\'in her sayfası iki sütunlu ve sütun başına çoğunlukla aynı sayıda satır içeren ünlü İncil baskısı bu özelliğinden dolayı hangi adla da anılır?', '42 satırlık İncil', ['36 satırlık İncil', '48 satırlık İncil', '30 satırlık İncil'], 'Gutenberg İncili\'nde sütunların çoğunda 42 satır bulunur; yaklaşık 180 nüsha basıldığı tahmin edilir.'),
  ('Don Kişot\'un yazarı Miguel de Cervantes\'in yaşamıyla ilgili aşağıdakilerden hangisi doğrudur?', 'İnebahtı\'da savaşarak yaralanmış, sonra yıllarca Cezayir\'de esir kalmıştır', ['Hayatı boyunca İspanya dışına hiç çıkmamış bir saray şairidir', 'Engizisyon mahkemesinde yargıç olarak uzun yıllar görev yapmıştır', 'Coğrafi keşiflere katılarak Peru\'da vali olarak görev yapmıştır'], 'Cervantes 1571\'de deniz savaşında sol elinden yaralandı; 1575\'te korsanlarca esir alınıp beş yıl Cezayir\'de tutuldu ve fidyeyle kurtarıldı.'),
  ('Fransa Kralı I. François\'nın 1525 Pavia Savaşı\'nda uğradığı sonuç hangisidir?', 'V. Karl\'ın ordusuna yenilip esir düşmesi ve Madrid\'e götürülmesi', ['Milano\'yu kesin olarak ele geçirip İtalya kralı ilan edilmesi', 'Papanın aracılığıyla imparatorla eşit şartlarda barış yapması', 'Savaş alanında öldürülerek tahtın oğluna geçmesi'], 'Pavia yenilgisinden sonra I. François, 1526 Madrid Antlaşması\'nı imzalayarak serbest kaldı ama koşullarına uymadı.'),
  ('Güneş merkezli evren modelini sistemli biçimde ortaya koyan \'Gök Kürelerinin Dönüşleri Üzerine\' adlı eser hangi yıl yayımlanmıştır?', '1543', ['1492', '1517', '1609'], 'Kopernik\'in eseri 1543\'te, yazarın ölüm yılında Nürnberg\'de basıldı. Aynı yıl Vesalius\'un anatomi kitabı da yayımlandı.'),
  ('Danimarka kralının kendisine verdiği Hven Adası\'nda kurduğu Uraniborg gözlemevinde teleskop olmadan son derece duyarlı gözlemler yapan astronom kimdir?', 'Tycho Brahe', ['Johannes Kepler', 'Nicolaus Kopernik', 'Christiaan Huygens'], 'Tycho, çıplak gözle ve büyük ölçüm aletleriyle gezegen konumlarını o güne dek görülmemiş bir kesinlikle kaydetti.'),
  ('Johannes Kepler\'in gezegenlerin Güneş çevresinde çember değil elips biçiminde yörüngelerde döndüğü sonucuna ulaşmasında en çok kimin gözlem verilerinden yararlandığı bilinir?', 'Tycho Brahe\'nin', ['Galileo Galilei\'nin', 'Nicolaus Kopernik\'in', 'Claudius Ptolemaios\'un'], 'Kepler, Prag\'da Tycho\'nun yardımcısıydı; onun Mars gözlemlerini çember yörüngelerle uzlaştıramayınca elips yörüngeyi önerdi.'),
  ('Evrenin sonsuz olduğunu ve sayısız dünya bulunduğunu savunan, sonunda 1600\'de Roma\'da Engizisyon kararıyla yakılan İtalyan düşünür kimdir?', 'Giordano Bruno', ['Tommaso Campanella', 'Paolo Sarpi', 'Pietro Pomponazzi'], 'Bruno\'nun mahkûmiyeti esas olarak dinî öğretilere aykırı bulunan görüşleri nedeniyle oldu; idamı Campo de\' Fiori meydanında gerçekleşti.'),
  ('Padua\'da insan kadavralarını bizzat inceleyerek Galenos\'un yüzyıllardır sorgulanmayan bazı anatomi bilgilerinin hayvan disseksiyonuna dayandığını gösteren hekim kimdir?', 'Andreas Vesalius', ['William Harvey', 'Ambroise Paré', 'Gabriele Falloppio'], 'Vesalius\'un 1543 tarihli \'İnsan Vücudunun Yapısı Üzerine\' adlı kitabı, ayrıntılı gravürleriyle modern anatominin başlangıcı sayılır.'),
  ('1628\'de yayımladığı eserinde kanın kalp tarafından pompalanarak vücutta sürekli dolaştığını deney ve hesaplarla gösteren İngiliz hekim kimdir?', 'William Harvey', ['Thomas Sydenham', 'Edward Jenner', 'Robert Hooke'], 'Harvey, kalbin bir saatte pompaladığı kan miktarının vücudun üretebileceğinden çok fazla olduğunu hesaplayarak kanın yeniden kullanıldığını kanıtladı.'),
  ('Francis Bacon\'un 1620 tarihli \'Novum Organum\'da önerdiği bilimsel yöntemin temel özelliği hangisidir?', 'Çok sayıda gözlem ve deneyden genel sonuçlara giden tümevarım', ['Kesin aksiyomlardan başlayan tümdengelimli matematiksel ispat', 'Antik otoritelerin görüşlerini karşılaştırarak ve tartışarak doğruyu bulma', 'Kutsal metinlerin yorumuyla doğa yasalarını belirleme'], 'Bacon, bilgiyi düzenli gözlem ve deneylerden derlemeyi önerdi; insan zihnini yanıltan önyargıları \'idoller\' olarak sınıflandırdı.'),
  ('1660\'ta Londra\'da kurulan ve \'Hiç kimsenin sözüne dayanma\' (Nullius in verba) düsturunu benimseyen bilim kurumu hangisidir?', 'Royal Society', ['Académie des sciences', 'Accademia dei Lincei', 'Berlin Bilimler Akademisi'], 'Royal Society, bilgiyi otoriteye değil deney ve gözleme dayandırma ilkesini düsturuyla vurguladı; Newton da sonradan başkanı oldu.'),
  ('Robert Hooke\'un 1665 tarihli \'Micrographia\' kitabında mantar dokusunu mikroskopla inceleyerek kullandığı ve bugün biyolojide temel bir terim hâline gelen kelime hangisidir?', 'Hücre', ['Atom', 'Gen', 'Doku'], 'Hooke, mantar kesitindeki küçük odacıkları manastır hücrelerine benzeterek \'cell\' adını verdi.'),
  ('Martin Luther\'in hukuk öğrenimini bırakıp Erfurt\'taki Augustinusçu manastıra girmesine yol açtığı anlatılan olay hangisidir?', 'Fırtınada yanına yıldırım düşünce keşiş olmaya adak adaması', ['Babasının ölümü üzerine mirasını kiliseye bağışlayıp yoksullara dağıtması', 'Roma\'ya yaptığı bir yolculukta papayla karşılaşması', 'Bir kitapçıda eline geçen Yunanca İncil\'i okuması'], '1505\'te Stotternheim yakınında fırtınaya yakalanan Luther, Azize Anna\'ya keşiş olacağına dair adak adadı ve sözünü tuttu.'),
  ('1517\'deki endüljans kampanyasında \'Sandıkta para şıngırdayınca ruh araftan sıçrar\' sözüyle anılan Dominiken vaiz kimdir?', 'Johann Tetzel', ['Johann Eck', 'Thomas Cajetan', 'Sylvester Prierias'], 'Tetzel\'in Saksonya sınırında yürüttüğü satışlar, Wittenberg halkını da çekince Luther\'in tepkisine yol açtı.'),
  ('Luther\'in 1520 Aralığında Wittenberg\'de, öğrencilerin önünde ateşe atarak kiliseyle bağlarını açıkça kopardığı belge hangisidir?', 'Kendisini aforozla tehdit eden papalık fermanı', ['İmparatorun kendisini sürgüne gönderen kararnamesi', 'Kendi yazdığı 95 Tez\'in ilk nüshası', 'Johann Tetzel\'in endüljans tarifesi'], '\'Exsurge Domine\' adlı papalık fermanı Luther\'e görüşlerini geri alması için süre veriyordu; Luther fermanı kanon hukuku kitaplarıyla birlikte yaktı.'),
  ('Luther\'in Wartburg Şatosu\'nda kaldığı sırada gerçekleştirdiği ve Alman dilinin birliğine de katkı sağladığı çalışma hangisidir?', 'Yeni Ahit\'i Yunancadan Almancaya çevirmesi', ['Augsburg İtirafnamesi\'ni kaleme alması', 'İlk Protestan ilmihalini Latince yazması', 'Bütün manastırların kapatılması için bir yasa hazırlaması'], 'Luther, 1522\'de yayımlanan Almanca Yeni Ahit\'i kısa sürede tamamladı; çevirisinin dili sonraki yüzyıllarda ortak yazı Almancasını etkiledi.'),
  ('Luther\'in 1525\'te eski bir rahibe olan Katharina von Bora ile evlenmesi, Protestan dünyasında hangi uygulamanın simgesi hâline gelmiştir?', 'Din adamlarının evlenebilmesi', ['Manastır yaşamının yeniden canlandırılması', 'Kadınların rahip olarak atanması', 'Boşanmanın tamamen yasaklanması'], 'Katolik Kilisesi rahiplerden bekârlık bekliyordu; Luther\'in evliliği ve ailesi, Protestan papaz evinin örnek modeli oldu.'),
  ('Luther\'in \'yalnız iman ile\' (sola fide) ilkesine göre insan Tanrı katında nasıl aklanır?', 'Tanrı\'nın lütfuna duyulan iman sayesinde', ['Kiliseye yapılan bağışların miktarı sayesinde', 'Hac ve oruç gibi ibadetlerin toplamı sayesinde', 'Azizlerin artan sevaplarının kendisine aktarılmasıyla'], 'Luther\'e göre kurtuluş insanın iyi işleriyle kazanılamaz; iyi işler imanın sonucudur, nedeni değil. Bu görüş endüljans mantığının temelini yıktı.'),
  ('\'Protestan\' adının kökeni hangi olaya dayanır?', '1529 Speyer Meclisi\'nde Lutherci prenslerin karara resmî itiraz sunması', ['Luther\'in 1517\'de tezlerini kilise kapısına asması', '1555 Augsburg Barışı\'nda yeni mezhebin imparatorluk belgelerinde resmen bu adla anılması', 'Trento Konsili\'nin Reformcuları bu adla kınaması'], 'Speyer\'de Lutherci prensler ve kentler \'protestatio\' adlı bir itiraz bildirisi sundu; \'Protestanlar\' adı buradan doğdu ve zamanla bütün Reform kiliselerine yayıldı.'),
  ('Lutherci inancın ana ilkelerini 1530 Augsburg Meclisi\'nde İmparator V. Karl\'a sunulmak üzere bir itirafname hâlinde yazan Luther\'in yakın çalışma arkadaşı kimdir?', 'Philipp Melanchthon', ['Martin Bucer', 'Andreas Osiander', 'Johannes Bugenhagen'], 'Luther imparatorluk yasağı altında olduğu için meclise gidemedi; Melanchthon\'un hazırladığı Augsburg İtirafnamesi Lutherci kiliselerin temel belgesi oldu.'),
  ('1531\'de Lutherci prenslerin ve kentlerin, imparatorun olası bir saldırısına karşı kurduğu savunma ittifakı hangisidir?', 'Schmalkalden Birliği', ['Kutsal Birlik', 'Swabya Birliği', 'Hansa Birliği'], 'Schmalkalden Birliği, V. Karl\'ın Osmanlı ve Fransa ile uğraştığı yıllarda Protestanları korudu; ancak 1546-47 savaşında yenildi.'),
  ('İsviçre\'de Reform\'u başlatan Huldrych Zwingli, 1519\'dan itibaren hangi kentin büyük kilisesinde vaiz olarak görev yapmıştır?', 'Zürih', ['Cenevre', 'Basel', 'Bern'], 'Zwingli, Zürih\'teki Grossmünster\'de İncil\'i baştan sona sırayla vaaz etmeye başladı; kent konseyi onun önerilerini adım adım yasalaştırdı.'),
  ('1529 Marburg Görüşmesi\'nde Luther ile Zwingli\'nin anlaşamadığı temel konu hangisidir?', 'Komünyon ayininde İsa\'nın ekmek ve şarapta gerçekten bulunup bulunmadığı', ['Bebeklerin vaftiz edilip edilmemesi gerektiği', 'Papanın kilisedeki otoritesinin kabul edilip edilmemesi ve piskoposların nasıl seçileceği', 'Endüljans satışının sürdürülüp sürdürülmemesi'], 'Luther İsa\'nın gerçek varlığında ısrar etti, Zwingli ise ayini simgesel bir anma olarak gördü; bu ayrılık Protestan cephesinin bölünmesine yol açtı.'),
  ('Zwingli\'nin hayatı nasıl sona ermiştir?', 'Katolik kantonlarla yapılan Kappel Savaşı\'nda 1531\'de öldürülmüştür', ['Engizisyon tarafından yakalanıp Roma\'ya götürülmüş ve orada yakılmıştır', 'Cenevre\'de Calvin\'in emriyle idam edilmiştir', 'Zürih\'te yaşlılıkla eceliyle ölmüştür'], 'İsviçre konfederasyonundaki Katolik ve Reformcu kantonlar arasındaki gerilim savaşa döndü; Zwingli, Zürih birlikleriyle birlikte savaşırken öldü.'),
  ('Jean Calvin\'in Protestan öğretiyi sistemli bir biçimde açıkladığı ve ilk baskısını 1536\'da Basel\'de yayımladığı başyapıtı hangisidir?', 'Hristiyan Dininin Esasları', ['Ortak Dua Kitabı', 'Augsburg İtirafnamesi', 'Ruhani Egzersizler'], 'Calvin\'in Institutio adlı eseri, ilk baskısında Fransa Kralı I. François\'ya ithaf edilmişti ve sonraki baskılarla büyük bir ilahiyat kitabına dönüştü.'),
  ('Cenevre\'de papazlar ile kent konseyinin seçtiği ihtiyarlardan oluşan ve yurttaşların ahlak ve inanç yaşamını denetleyen kurula ne ad verilirdi?', 'Konsistuar', ['Sinod', 'Signoria', 'Kuria'], 'Konsistuar; kumar, küfür, dans ve ayine gelmeme gibi davranışları inceleyip uyarı, kınama ve kilise dışı bırakma gibi yaptırımlar uyguluyordu.'),
  ('Teslis (üçleme) öğretisini reddettiği için 1553\'te Calvin\'in de onayıyla Cenevre\'de yakılarak idam edilen İspanyol hekim ve ilahiyatçı kimdir?', 'Mikael Servetus', ['Sebastian Castellio', 'Bernardino Ochino', 'Fausto Sozzini'], 'Servetus\'un idamı, Castellio\'nun \'Bir insanı öldürmek bir öğretiyi savunmak değildir\' diyerek dinî hoşgörü tartışmasını başlatmasına yol açtı.'),
  ('Cenevre\'de Calvin\'in yanında bulunduktan sonra ülkesine dönerek 1560\'ta İskoçya\'da Presbiteryen kilisesinin kurulmasına önderlik eden reformcu kimdir?', 'John Knox', ['George Wishart', 'Andrew Melville', 'Thomas Cartwright'], 'Knox, Katolik İskoç Kraliçesi Mary Stuart\'la çatıştı; kurduğu kilise piskoposlar yerine ihtiyarlar kuruluyla (presbitery) yönetiliyordu.'),
  ('1534\'te İngiliz parlamentosunun çıkardığı ve kralı \'İngiltere Kilisesi\'nin yeryüzündeki tek yüce başı\' ilan eden yasa hangisidir?', 'Üstünlük Yasası', ['Haklar Bildirgesi', 'Birlik Yasası', 'Hoşgörü Yasası'], 'Üstünlük Yasası (Act of Supremacy), papanın İngiltere üzerindeki yetkisini tümüyle kaldırarak kilisenin başı olarak hükümdarı tanıdı.'),
  ('VI. Edward döneminde Başpiskopos Thomas Cranmer\'in hazırladığı ve İngiliz kiliselerinde ayinin İngilizce yapılmasını sağlayan kitap hangisidir?', 'Ortak Dua Kitabı', ['Kral James İncili', 'Otuz Dokuz Madde', 'Şehitler Kitabı'], '1549\'da yayımlanan Book of Common Prayer, Latince ayinin yerini aldı; düzeltilmiş biçimleri yüzyıllarca Anglikan ibadetinin temeli oldu.'),
  ('I. Mary (Mary Tudor) döneminde İngiltere\'de uygulanan dinî politika hangisidir?', 'Katolikliğe geri dönülmesi ve yüzlerce Protestanın yakılarak idam edilmesi', ['Protestanlığın resmî din yapılıp Katoliklerin sürgüne gönderilmesi', 'Bütün mezheplere tam din özgürlüğü tanınması', 'Anglikan Kilisesi\'nin İskoç Presbiteryen kilisesiyle birleştirilmesi ve piskoposların kaldırılması'], 'Mary, papanın otoritesini yeniden tanıdı; Cranmer dahil yaklaşık 280 Protestanın yakılması ona \'Kanlı Mary\' lakabını kazandırdı.'),
  ('Papa X. Leo\'nun 1521\'de Luther\'e karşı yazdığı bir risale nedeniyle VIII. Henry\'ye verdiği ve İngiliz hükümdarlarının hâlâ kullandığı unvan hangisidir?', 'İnancın Savunucusu', ['En Hristiyan Kral', 'Katolik Kral', 'Havarisel Kral'], 'Henry \'Yedi Sakramentin Savunusu\'nu yazınca Fidei Defensor unvanını aldı; kiliseden ayrıldıktan sonra da unvan parlamentoca korunmuştur.'),
  ('Yeni Ahit\'i Yunancadan İngilizceye çevirip yurt dışında bastıran ve 1536\'da Brüksel yakınlarında yakılarak idam edilen çevirmen kimdir?', 'William Tyndale', ['Miles Coverdale', 'John Rogers', 'Hugh Latimer'], 'Tyndale\'in çevirisi, sonraki İngilizce Kutsal Kitap çevirilerinin, özellikle 1611 Kral James sürümünün temelini oluşturdu.'),
  ('Trento Konsili\'nin din adamlarının eğitimiyle ilgili aldığı ve uzun vadede en etkili olan kararı hangisidir?', 'Her piskoposlukta rahip yetiştirecek bir seminer açılması', ['Rahiplerin evlenmesine izin verilmesi', 'Rahiplik eğitiminin yalnız Roma\'daki papalık okullarında yapılması zorunluluğu', 'Rahiplerin Latince öğrenmesinin yasaklanması'], 'Seminerler, eğitimsizlikleri eleştirilen kırsal din adamlarının yerine iyi yetişmiş bir rahip kuşağı oluşturmayı amaçladı.'),
  ('Trento Konsili\'nin Protestanların \'yalnız Kutsal Kitap\' ilkesine verdiği yanıt hangisidir?', 'Kutsal Kitap\'ın yanında kilise geleneğini de bağlayıcı saymak', ['Kutsal Kitap\'ın okunmasını bütünüyle yasaklamak', 'Luther\'in Almanca çevirisini resmî metin olarak kabul etmek', 'Kilise geleneğinin hiçbir bağlayıcılığı olmadığını kabul edip yalnız konsil kararlarına uymak'], 'Konsil, vahyin hem yazılı metinde hem de havarilerden gelen gelenekte korunduğunu söyledi ve Latince Vulgata\'yı resmî metin ilan etti.'),
  ('Hindistan\'da Goa\'dan başlayıp 1549\'da Japonya\'ya kadar ulaşan ve Asya\'da misyonerlik yapan Cizvit tarikatının kurucularından kimdir?', 'Francisco Javier', ['Pierre Favre', 'Diego Laínez', 'Peter Canisius'], 'Loyola\'nın Paris\'teki ilk arkadaşlarından Javier, Portekiz\'in Asya\'daki ticaret ağını kullanarak Hindistan, Malakka ve Japonya\'da çalıştı.'),
  ('Karmelit rahibe tarikatını daha sade ve sıkı bir düzene kavuşturan, mistik yazılarıyla tanınan 16. yüzyıl İspanyol azizesi kimdir?', 'Avilalı Teresa', ['Sienalı Katerina', 'Jeanne d\'Arc', 'Assisili Klara'], 'Avilalı Teresa, \'İç Kale\' gibi eserlerinde ruhun Tanrı\'ya yükselişini anlattı; Karşı-Reform\'un dinî canlanmasının simgelerindendir.'),
  ('Gerçekçi figürleri ve karanlık arka plandan sert ışıkla çıkan sahneleriyle Barok resmi derinden etkileyen, şiddetli yaşamıyla da bilinen İtalyan ressam kimdir?', 'Caravaggio', ['Annibale Carracci', 'Guido Reni', 'Artemisia Gentileschi'], 'Caravaggio\'nun ışık-gölge kullanımı (tenebrizm) ve sokaktan alınmış modelleri, dinî sahneleri sıradan insanlara yakın kıldı.'),
  ('1562\'de Guise Dükü\'nün adamlarının bir ahırda ibadet eden Protestanlara saldırması hangi sonucu doğurmuştur?', 'Fransız Din Savaşları\'nın başlamasını', ['Nantes Fermanı\'nın yayımlanmasını', 'Guise ailesinin Fransa\'dan sürülmesini', 'Fransa\'nın Protestan bir krallığa dönüşmesini'], 'Vassy Katliamı, Katolik ve Hugenot soylular arasında gerilen ilişkileri silahlı çatışmaya dönüştürdü; savaşlar aralıklarla 1598\'e kadar sürdü.'),
  ('1587-1589 yılları arasındaki \'Üç Henri Savaşı\'nda karşı karşıya gelen üç Henri aşağıdakilerden hangisinde doğru verilmiştir?', 'III. Henri, Guise Dükü Henri ve Navarralı Henri', ['II. Henri, IV. Henri ve VIII. Henry', 'III. Henri, Condé Prensi Henri ve İngiliz VIII. Henry', 'Navarralı Henri, Tudor Henry ve Portekizli Henrique'], 'Kral III. Henri, Katolik Birliği\'nin önderi Guise Dükü ve Hugenot önderi Navarra Kralı arasında taht ve din mücadelesi yaşandı.'),
  ('Fransa\'yı din savaşlarından sonra toparlayan IV. Henri\'nin 1610\'daki ölümü nasıl gerçekleşmiştir?', 'Paris\'te arabasındayken bağnaz bir Katolik tarafından bıçaklanmıştır', ['Bir av kazasında attan düşerek ölmüştür', 'İspanya\'ya karşı yürütülen bir kuşatmada cephede yaralanarak ölmüştür', 'Veba salgınında hastalanarak ölmüştür'], 'François Ravaillac\'ın düzenlediği suikast, IV. Henri\'yi tam da Habsburglara karşı yeni bir sefere hazırlanırken öldürdü.'),
  ('II. Felipe\'nin 1567\'de Felemenk\'e gönderdiği Alba Dükü\'nün kurduğu ve binlerce kişiyi yargılayan mahkeme halk arasında hangi adla anılmıştır?', 'Kan Konseyi', ['Yıldız Odası', 'Kara Kurul', 'Yüksek Divan'], 'Resmî adı \'Karışıklıklar Konseyi\' olan mahkeme, Egmont ve Horn kontları dahil pek çok kişiyi idama mahkûm etti ve direnişi daha da büyüttü.'),
  ('Hollanda isyanının önderi olan ve düşüncelerini gizlemedeki ustalığı nedeniyle \'Sessiz\' lakabıyla anılan Orange Prensi Wilhelm\'in sonu nasıl olmuştur?', '1584\'te Delft\'te tabancayla vurularak öldürülmüştür', ['İspanyollarca yakalanıp Brüksel\'deki büyük meydanda idam edilmiştir', 'Leiden kuşatmasında top ateşiyle ölmüştür', 'İngiltere\'ye sürgün edilip orada ölmüştür'], 'II. Felipe\'nin başına ödül koyduğu Wilhelm, Balthasar Gérard tarafından vuruldu; ateşli silahla öldürülen ilk devlet önderlerinden sayılır.'),
  ('1574\'te İspanyolların kuşattığı Leiden\'in kurtarılması için Hollandalıların başvurduğu yöntem hangisidir?', 'Setleri yıkarak çevredeki toprakları su altında bırakmak', ['Kenti tamamen yakarak İspanyollara yalnız kül ve yıkıntı bırakmak', 'İspanyol komutanlara büyük fidye ödemek', 'Fransız ordusunu yardıma çağırmak'], 'Setlerin açılmasıyla sular yükseldi ve Deniz Dilencileri gemilerle kente yardım ulaştırdı; ertesi yıl ödül olarak Leiden Üniversitesi kuruldu.'),
  ('İspanya ile Birleşik Eyaletler arasında 1609\'da imzalanan ve 1621\'e kadar süren ateşkes hangi adla bilinir?', 'On İki Yıl Ateşkesi', ['Yedi Yıl Ateşkesi', 'Otuz Yıl Ateşkesi', 'Dokuz Yıl Ateşkesi'], 'Bu ateşkes İspanya\'nın Hollanda\'yı fiilen tanıması anlamına geliyordu; savaş 1621\'de yeniden başladı ve 1648 Münster Barışı\'na kadar sürdü.'),
  ('15. yüzyılda Portekizlilerin kullandığı karavela gemilerinin keşifler açısından en önemli üstünlüğü hangisidir?', 'Üçgen yelkenleri sayesinde rüzgâra karşı da seyredebilmesi', ['Kürekçilerle yürütülerek rüzgârsız havada hızla ilerleyebilmesi', 'Yüzlerce top taşıyabilecek büyüklükte olması', 'Buharla çalışan bir makineye sahip olması'], 'Latin (üçgen) yelkenler, karavelanın rüzgâra yakın açılarla seyretmesini sağladı; bu, Afrika kıyısından dönüş yolculuklarında kritik önemdeydi.'),
  ('Açık denizde bir geminin enlemini belirlemek için denizcilerin usturlap ya da kadranla yaptığı ölçüm hangisidir?', 'Kutup Yıldızı\'nın ya da öğle güneşinin ufuktan yüksekliğini ölçmek', ['Geminin hızını düğümlü bir ip ve suya atılan bir kütükle ölçüp hesaplamak', 'Pusula iğnesinin sapma açısını ölçmek', 'Gelgit yüksekliğini kıyıdan ölçmek'], 'Gök cisimlerinin ufuk üzerindeki açısı enlemi verir; boylam ise güvenilir deniz saatleri geliştirilene kadar 18. yüzyıla dek sorun olarak kaldı.'),
  ('Akdeniz denizcilerinin kullandığı, kıyı çizgilerini ve limanları ayrıntılı gösteren, üzerinde rüzgâr gülünden çıkan yön çizgileri bulunan haritalara ne ad verilir?', 'Portolan haritaları', ['T-O haritaları', 'Mappa mundi', 'Kadastro haritaları'], 'Portolanlar, pusula yönlerine dayalı pratik seyir haritalarıydı; T-O haritaları ve mappa mundi ise daha çok dinî-simgesel dünya tasvirleriydi.'),
  ('Avrupalıları Afrika\'nın ya da Asya\'nın içlerinde bir yerde yaşadığına inanılan güçlü bir Hristiyan hükümdarı aramaya yönelten efsane hangisidir?', 'Rahip John efsanesi', ['El Dorado efsanesi', 'Atlantis efsanesi', 'Kutsal Kâse efsanesi'], 'Portekizliler bu hükümdarı Müslümanlara karşı bir müttefik olarak arıyordu; efsane zamanla Etiyopya\'daki Hristiyan krallıkla özdeşleştirildi.'),
  ('Gerardus Mercator\'ın 1569\'da geliştirdiği harita izdüşümünün denizciler için önemi nedir?', 'Sabit pusula yönündeki rotaların haritada düz çizgi olarak görünmesi', ['Bütün kıtaların alanlarının gerçek oranlarıyla ve hiç bozulmadan gösterilmesi', 'Kutup bölgelerinin en küçük biçimde gösterilmesi', 'Denizlerin derinliğinin renklerle gösterilmesi'], 'Mercator izdüşümünde açılar korunur; bu yüzden sabit pusula açısıyla izlenen rota düz çizgi olur. Buna karşılık kutuplara yaklaştıkça alanlar büyür.'),
  ('1488\'de Afrika\'nın güney ucunu dolaşan Bartolomeu Dias\'ın bu buruna verdiği ilk adın Portekiz kralınca değiştirilmesinin nedeni hangisidir?', 'Hindistan\'a deniz yolunun açılacağı umudunu yansıtan bir ad istenmesi', ['Dias\'ın kraldan izinsiz sefere çıkması üzerine adının haritalardan silinmek istenmesi', 'Burnun daha önce başka bir ülke tarafından adlandırılmış olması', 'Kralın adını buruna vermek istemesi ve kendini ölümsüzleştirmesi'], 'Dias buruna sert havalar nedeniyle \'Fırtınalar Burnu\' dedi; II. João ise Hindistan yolunun açılması umuduyla adı \'Ümit Burnu\' olarak değiştirdi.'),
  ('Vasco da Gama\'nın 1498\'de Afrika\'yı dolaşarak ulaştığı ve Avrupa\'dan Hindistan\'a deniz yolunun açıldığı liman kenti hangisidir?', 'Kalikut', ['Goa', 'Bombay', 'Kalküta'], 'Gama, Doğu Afrika\'daki Malindi\'den aldığı bir kılavuzun yardımıyla Hint Okyanusu\'nu geçerek Malabar kıyısındaki Kalikut\'a vardı.'),
  ('1500\'de Hindistan\'a giden büyük bir Portekiz filosuyla Atlantik\'te batıya fazla açılınca Güney Amerika kıyısına varan ve bu toprağı Portekiz adına sahiplenen komutan kimdir?', 'Pedro Álvares Cabral', ['Fernão de Magalhães', 'Francisco de Almeida', 'Tristão da Cunha'], 'Cabral\'ın Brezilya kıyısına ulaşması, Tordesillas çizgisinin doğusunda kalan bu toprağın Portekiz\'e ait olmasının temelini oluşturdu.'),
  ('1510\'da Goa\'yı, 1511\'de Malakka\'yı ve 1515\'te Hürmüz\'ü alarak Portekiz\'in Asya\'daki üs ağını kuran komutan kimdir?', 'Afonso de Albuquerque', ['Francisco de Almeida', 'Vasco da Gama', 'Nuno da Cunha'], 'Albuquerque, Hint Okyanusu\'na açılan dar geçitleri denetleyerek baharat ticaretini Portekiz\'in kontrolüne almayı hedefledi.'),
  ('Kolomb\'un 1492\'deki ilk yolculuğunda kullandığı üç gemi aşağıdakilerden hangisinde doğru verilmiştir?', 'Santa María, Pinta ve Niña', ['Victoria, Trinidad ve Concepción', 'Golden Hind, Pelican ve Swan', 'São Gabriel, São Rafael ve Berrio'], 'Kolomb Santa María\'nın kaptanıydı; Pinta ve Niña\'yı Pinzón kardeşler yönetti. Diğer seçenekler Magellan, Drake ve Vasco da Gama filolarına aittir.'),
  ('Kolomb\'un filosu 12 Ekim 1492\'de Atlantik\'i geçtikten sonra ilk olarak nereye ulaşmıştır?', 'Bahamalar\'daki bir adaya', ['Florida yarımadasına', 'Brezilya kıyısına', 'Panama Kıstağı\'na'], 'Yerlilerin Guanahani dediği adaya Kolomb \'San Salvador\' adını verdi; ardından Küba ve Hispaniola\'ya geçti.'),
  ('Kolomb\'un yaşamı boyunca ulaştığı toprakların yeni bir kıta olduğunu kabul etmeyip neresi olduğuna inandığı bilinmektedir?', 'Asya\'nın doğu kıyıları ve çevresindeki adalar', ['Afrika\'nın batı kıyıları', 'Avrupa\'nın kuzeyindeki adalar', 'Efsanevi Atlantis\'in batan kıtasından kalan kalıntılar'], 'Kolomb dört yolculuk yaptı ve 1506\'da öldüğünde hâlâ Asya\'ya yakın bölgelere vardığını düşünüyordu; \'Batı Hint Adaları\' adı bu yanılgının mirasıdır.'),
  ('Tordesillas Antlaşması\'nın Güney Amerika\'da bugün de görülen kalıcı bir sonucu hangisidir?', 'Brezilya\'da Portekizce, kıtanın çoğunda İspanyolca konuşulması', ['Kıtada İngilizcenin resmî dil olması', 'Bütün kıtanın tek bir devlet olarak kalması', 'Güney Amerika\'da hiçbir Avrupa dilinin yerleşmemesi ve yerli dillerin resmî olması'], 'Çizginin doğusundaki topraklar Portekiz\'e düştü; Brezilya\'nın dili ve kültürü bu paylaşımın izlerini taşır.'),
  ('1497\'de İngiltere Kralı VII. Henry adına Atlantik\'i geçerek Kuzey Amerika kıyısına, büyük olasılıkla Newfoundland\'e ulaşan İtalyan asıllı denizci kimdir?', 'Giovanni Caboto', ['Giovanni da Verrazzano', 'Sebastiano Caboto', 'Amerigo Vespucci'], 'Cabot\'un yolculuğu, İngiltere\'nin sonraki yüzyıllarda Kuzey Amerika üzerinde hak iddia etmesinin dayanaklarından biri oldu.'),
  ('1513\'te Panama Kıstağı\'nı karadan geçerek Pasifik Okyanusu\'nu gören ilk Avrupalı olan ve buna \'Güney Denizi\' adını veren İspanyol kimdir?', 'Vasco Núñez de Balboa', ['Hernando de Soto', 'Juan Ponce de León', 'Francisco de Orellana'], 'Balboa, kıstağın dağlarından okyanusu görüp sahile inerek onu İspanya kralı adına sahiplendi.'),
  ('Fransa Kralı I. François adına 1534-1536 yolculuklarında Saint-Laurent (St. Lawrence) Irmağı\'nı keşfeden ve bölgenin adının yerel bir \'köy\' kelimesinden gelmesine aracılık eden denizci kimdir?', 'Jacques Cartier', ['Samuel de Champlain', 'Jean Ribault', 'Pierre Le Moyne d\'Iberville'], 'Cartier\'nin yerlilerden duyduğu \'kanata\' (köy, yerleşim) kelimesi, zamanla bütün bölgenin adı olan Kanada\'ya dönüştü.'),
  ('Kuzeybatı Geçidi\'ni ararken adını taşıyan ırmağı Hollandalılar, adını taşıyan büyük körfezi ise İngilizler adına keşfeden ve 1611\'de mürettebatının isyanı sonucu bir kayığa bindirilip denize bırakılan kaşif kimdir?', 'Henry Hudson', ['Martin Frobisher', 'John Davis', 'William Baffin'], 'Hudson 1609\'da Hollanda Doğu Hindistan Şirketi adına bugünkü Hudson Irmağı\'nı araştırdı; 1610-11\'de İngiltere adına Hudson Körfezi\'ne ulaştı.'),
  ('1577-1580 yılları arasında Golden Hind adlı gemisiyle dünyanın çevresini dolaşan ve yol boyunca İspanyol gemilerini yağmalayan İngiliz denizci kimdir?', 'Francis Drake', ['Walter Raleigh', 'John Hawkins', 'Thomas Cavendish'], 'Drake, dünyanın çevresini dolaşmayı kendi komutasında tamamlayan ilk kaptandır; I. Elizabeth onu 1581\'de gemisinin güvertesinde şövalye ilan etti.'),
  ('Magellan\'ın Güney Amerika\'nın güney ucundaki dar geçidi aştıktan sonra girdiği okyanusa \'Pasifik\' adını vermesinin nedeni hangisidir?', 'Geçitteki fırtınalardan sonra karşılaştığı suların sakin görünmesi', ['Okyanusun kıyılarında barışçı halklarla karşılaşması', 'İspanya ile Portekiz arasında barış imzalanmış olması', 'Okyanusun haritalarda zaten bu adla yer alması'], 'Pasifik \'barışçıl, sakin\' anlamına gelir; ancak okyanusu geçiş aylar sürdü ve mürettebat açlık ile iskorbüt yüzünden ağır kayıplar verdi.'),
  ('Magellan\'ın 1521\'de hayatını kaybettiği yer neresidir?', 'Filipinler\'deki Mactan Adası', ['Endonezya\'daki Moluk Adaları', 'Güney Amerika\'daki Patagonya', 'Afrika\'daki Ümit Burnu'], 'Magellan, yerel önder Lapulapu\'nun savaşçılarıyla girdiği çatışmada öldü; yolculuğu Elcano yönetiminde sürdü.'),
  ('16. yüzyılda Avrupa\'da fiyatların yüzyıl boyunca birkaç kat artmasına verilen \'Fiyat Devrimi\' adının arkasındaki en çok vurgulanan etken hangisidir?', 'Amerika\'dan büyük miktarda gümüş akması ve nüfus artışı', ['Avrupa\'da madenî paranın tamamen kaldırılması', 'Baharat fiyatlarının sıfıra düşmesi', 'Bütün ülkelerin kâğıt paraya geçmesi'], 'Amerikan gümüşü para arzını artırdı; aynı dönemde artan nüfusun tarım ürünlerine talebi de fiyatları yükseltti. Tarihçiler iki etkenin payını tartışır.'),
  ('16. ve 17. yüzyıllarda Avrupa devletlerinin uyguladığı merkantilist politikanın temel varsayımı hangisidir?', 'Bir ülkenin zenginliğinin biriktirdiği altın ve gümüşle ölçüldüğü', ['Serbest ticaretin bütün ülkelere eşit kazanç sağladığı', 'Devletin ekonomiye hiç karışmaması gerektiği', 'Tarımın tek gerçek üretken sektör olduğu'], 'Merkantilistler ihracatı artırıp ithalatı kısıtlayarak ülkeye değerli maden girişini sağlamayı hedefledi; bu, gümrük duvarları ve sömürge tekellerini doğurdu.'),
  ('Merkantilist bir devlet sömürgeleriyle ilişkilerini düzenlerken aşağıdaki politikalardan hangisini izlemesi beklenir?', 'Sömürgelerin hammadde sağlayıp yalnız ana ülkeyle ticaret yapmasını zorunlu kılmak', ['Sömürgelerin rakip ülkelere serbestçe ticaret yapmasını teşvik etmek', 'Sömürgelerde ana ülkeyle rekabet edecek sanayiler kurmak', 'Sömürgelerden hiçbir vergi ya da ürün almamak'], 'Merkantilizmde sömürgeler hammadde kaynağı ve mamul ürün pazarıydı; İngiliz Seyrüsefer Yasaları ve İspanya\'nın Sevilla tekeli bunun örnekleridir.'),
  ('Amerika\'dan Avrupa\'ya getirilen ürünlerden hangisi, birim alandan yüksek kalori sağlaması nedeniyle özellikle 18. yüzyıldan itibaren Kuzey Avrupa\'da nüfus artışına en çok katkıda bulunan besin olarak öne çıkar?', 'Patates', ['Kahve', 'Tütün', 'Kakao'], 'Patates, soğuk iklimlerde ve küçük tarlalarda bile bol ürün veriyordu; İrlanda ve Prusya gibi bölgelerde yoksulların temel besini oldu.'),
  ('Coğrafi Keşifler\'in ardından ticaretin ağırlık merkezinin Atlantik kıyısına kaymasıyla 16. yüzyıl başında Portekiz baharatının ve Güney Alman bakırının buluştuğu en büyük ticaret merkezi hangi kent olmuştur?', 'Anvers', ['Venedik', 'Ceneviz', 'Marsilya'], 'Anvers, Portekiz\'in baharat dağıtım merkezi ve uluslararası bankacılığın odağı oldu; kentin borsası 1531\'de açıldı.'),
  ('1602\'de kurulan ve hisselerini halka satarak tarihin ilk büyük anonim şirketlerinden biri olan Hollanda Doğu Hindistan Şirketi\'nin kısaltması hangisidir?', 'VOC', ['WIC', 'EIC', 'BEIC'], 'Vereenigde Oost-Indische Compagnie (VOC), Asya ticaretinde tekel hakkı aldı; savaş açma, antlaşma yapma ve kale kurma yetkileriyle neredeyse bir devlet gibi çalıştı.'),
  ('Hollanda Doğu Hindistan Şirketi\'nin Asya\'daki yönetim merkezi olarak 1619\'da Cava Adası\'nda kurduğu kent hangi adı taşıyordu?', 'Batavya', ['Malakka', 'Ambon', 'Makassar'], 'Jan Pieterszoon Coen\'in kurduğu Batavya, bugünkü Cakarta\'dır; şirketin baharat ağının merkezi oldu.'),
  ('Hollanda Doğu Hindistan Şirketi\'nin 1652\'de Afrika\'nın güney ucunda bir yerleşim kurmasının asıl amacı hangisidir?', 'Asya yolundaki gemilere su ve taze yiyecek sağlayan bir ikmal noktası kurmak', ['Afrika\'nın iç bölgelerindeki altın madenlerini işletmek', 'Portekiz\'in Brezilya\'daki topraklarına saldırı üssü kurmak', 'Avrupa\'dan getirilen suçluları ve borçluları sürgün edip yeni bir ceza kolonisi kurmak'], 'Jan van Riebeeck\'in kurduğu Kap yerleşimi başlangıçta bir ikmal noktasıydı; zamanla Boer toplumunun çekirdeği oldu.'),
  ('Hollanda\'da 1630\'ların ortasında belirli çiçek soğanlarının fiyatlarının aşırı yükselip 1637 başında aniden çökmesi olayı genellikle hangi adla anılır?', 'Lale çılgınlığı', ['Güney Denizi balonu', 'Mississippi balonu', 'Kara Cuma'], 'Lale çılgınlığı, spekülatif fiyat balonlarının erken örneği olarak anılır; ekonomiye etkisinin büyüklüğü tarihçiler arasında tartışmalıdır.'),
  ('Hugo Grotius\'un 1609\'da yayımladığı \'Mare Liberum\' (Özgür Deniz) adlı eserinde savunduğu düşünce hangisidir?', 'Denizlerin hiçbir devletin mülkü olamayacağı ve ticarete açık kalması gerektiği', ['Denizlerin papalığın paylaştırdığı biçimde yalnız İspanya ve Portekiz\'e ait olduğu', 'Her devletin kıyısından itibaren bütün okyanusa sahip olduğu', 'Denizde ticaretin yalnız savaş gemileriyle yapılabileceği'], 'Grotius, Portekiz\'in Asya denizlerinde tekel iddiasına karşı Hollanda\'nın ticaret hakkını savundu; İngiliz John Selden ise \'Kapalı Deniz\' ile yanıt verdi.'),
  ('1667 Breda Antlaşması\'yla İngiltere\'ye bırakılan Hollanda kolonisi Yeni Amsterdam\'ın bugünkü adı nedir?', 'New York', ['Boston', 'Philadelphia', 'Baltimore'], 'İngilizler kenti 1664\'te ele geçirip York Dükü\'nün adını verdi; Breda\'da Hollanda kenti bıraktı, karşılığında Surinam\'ı ve Banda\'daki Run Adası üzerindeki hakları tuttu.'),
  ('17. yüzyıldaki İngiliz-Hollanda deniz savaşlarının başlıca nedeni hangisidir?', 'İki ülke arasındaki ticaret ve taşımacılık rekabeti', ['Hollanda\'nın Katolik, İngiltere\'nin Protestan olması', 'Hollanda\'nın İngiliz tahtı üzerinde hak iddia etmesi', 'İngiltere\'nin Hollanda\'ya karşı İspanya ile ittifak yapması'], 'İki Protestan deniz gücü arasında savaşlar çıkmasının temel nedeni ekonomik rekabetti; İngiltere\'nin 1651 Seyrüsefer Yasası Hollanda taşımacılığını doğrudan hedef alıyordu.'),
  ('Ferdinand ve Isabella\'nın 1478\'de papalıktan izin alarak kurduğu, ancak doğrudan krallara bağlı olarak çalışan kurum hangisidir?', 'İspanyol Engizisyonu', ['Roma Engizisyonu', 'Casa de Contratación', 'Santa Hermandad'], 'İspanyol Engizisyonu öncelikle Hristiyanlığa geçmiş Yahudi ve Müslümanların inançlarını gizlice sürdürüp sürdürmediğini soruşturdu; ilk başengizisyoncusu Tomás de Torquemada\'dır.'),
  ('1492\'de İspanya\'da çıkarılan Elhamra Fermanı\'nın içeriği hangisidir?', 'Hristiyanlığa geçmeyen Yahudilerin krallıktan sürülmesi', ['Müslümanlara ve Yahudilere tam din özgürlüğü tanınması ve eşit haklar verilmesi', 'Engizisyonun kaldırılması', 'Kolomb\'un yolculuğunun finanse edilmesi'], 'Fermana göre din değiştirmeyen Yahudiler birkaç ay içinde ülkeyi terk etmek zorundaydı; sürgün edilenlerin bir kısmı Osmanlı topraklarına, Kuzey Afrika\'ya ve İtalya\'ya yerleşti.'),
  ('V. Karl\'ın (Şarlken) aynı anda İspanya, Felemenk ve Avusturya Habsburg topraklarına sahip olmasının nedeni hangisidir?', 'Habsburg, Burgonya, Kastilya ve Aragon miraslarının onda birleşmesi', ['Bu toprakları kendi seferleriyle tek tek fethetmesi ve yerel hanedanları devirmesi', 'Papanın ona bütün Avrupa\'yı bağışlaması', 'Fransa kralıyla yaptığı bir toprak takası'], 'Annesi Juana\'dan İspanyol krallıklarını, babası Güzel Philippe\'ten Burgonya mirasını, dedesi Maximilian\'dan Habsburg topraklarını aldı.'),
  ('V. Karl\'ın 1519\'da Kutsal Roma imparatoru seçilmesinde rakibi Fransa Kralı I. François\'ya üstün gelmesini sağlayan etken hangisidir?', 'Fugger bankasının sağladığı büyük borç', ['Papanın Fransa kralını aforoz etmiş olması ve seçici prenslerin buna uyması', 'Fransa\'nın seçime aday göstermemesi', 'Seçici prenslerin tümünün İspanyol olması'], 'Seçim, prenslere dağıtılan büyük paralarla kazanıldı; Jakob Fugger daha sonra imparatora bu borcu sert bir mektupla hatırlatmıştır.'),
  ('V. Karl\'ın 1556\'da tahttan çekilirken topraklarını nasıl paylaştırdığı bilinmektedir?', 'İspanya ve Felemenk oğlu Felipe\'ye, Avusturya ve imparatorluk kardeşi Ferdinand\'a kaldı', ['Bütün topraklar tek bir varis olarak oğlu II. Felipe\'ye geçti ve imparatorluk İspanya\'ya bağlandı', 'Toprakları papaya ve Fransa kralına bırakıldı', 'İspanya kardeşi Ferdinand\'a, Avusturya oğlu Felipe\'ye kaldı'], 'Bu paylaşım Habsburg hanedanını İspanyol ve Avusturya kollarına ayırdı; V. Karl son yıllarını Yuste Manastırı\'nda geçirdi.'),
  ('II. Felipe\'nin Madrid yakınlarında yaptırdığı, saray, manastır, kütüphane ve kraliyet mezarlığını tek bir yapıda birleştiren devasa kompleks hangisidir?', 'El Escorial', ['Elhamra Sarayı', 'Alcázar', 'Buen Retiro'], 'El Escorial, II. Felipe\'nin dindar ve bürokratik yönetim anlayışını yansıtır; kral imparatorluğu buradan yazışmalarla yönetti.'),
  ('II. Felipe\'nin 1580\'de Portekiz tahtını da ele geçirmesi İspanya\'ya ne kazandırmıştır?', 'Portekiz\'in Asya, Afrika ve Brezilya\'daki sömürgelerini', ['Fransa tahtı üzerinde kesin bir veraset hakkı elde etmesini', 'Hollanda isyanının hemen sona ermesini', 'İngiltere ile kalıcı bir ittifak kurmasını'], 'İber Birliği 1640\'a kadar sürdü; ancak bu birleşme Portekiz sömürgelerini İspanya\'nın düşmanı olan Hollanda\'nın hedefi hâline de getirdi.'),
  ('VII. Henry\'nin York hanedanından Elizabeth ile evlenmesinin simgesi olarak kullanılan ve iki renkli gülü birleştiren arma hangisidir?', 'Tudor gülü', ['Stuart devedikeni', 'Plantagenet aslanı', 'Galler ejderi'], 'Lancaster\'ın kırmızı ve York\'un beyaz gülünü birleştiren Tudor gülü, iç savaşın sona erdiğinin ve hanedan birliğinin simgesiydi.'),
  ('1568\'de ülkesinden kaçarak İngiltere\'ye sığınan, yaklaşık on dokuz yıl gözetim altında tutulduktan sonra 1587\'de idam edilen İskoç kraliçesi kimdir?', 'Mary Stuart', ['Mary Tudor', 'Margaret Tudor', 'Marie de Guise'], 'Katolik Mary Stuart, Elizabeth\'in yerine geçirilmek istendiği komplolarla adı anılınca Babington Komplosu\'ndan sonra idam edildi; oğlu sonradan İngiltere kralı oldu.'),
  ('1588\'de İspanyol Armadası\'nın Calais açıklarında demirlediği gece İngilizlerin uyguladığı ve İspanyol düzenini bozan taktik hangisidir?', 'Yanan ateş gemilerini rüzgârla İspanyol filosunun üzerine salmak', ['Armada\'nın gemilerine çıkarma yapıp onları tek tek ele geçirmek', 'Limanın girişini zincirle kapatarak Armada\'yı kuşatmak', 'İspanyol amirali rüşvetle taraf değiştirmeye ikna etmek'], 'Ateş gemilerinden kaçmak için demir halatlarını kesen İspanyol gemileri dağıldı; ertesi gün Gravelines\'de savaş yapıldı, fırtınalar da Armada\'nın sonunu getirdi.'),
  ('Walter Raleigh\'in 1580\'lerde Kuzey Amerika\'da kurmaya çalıştığı koloniye verilen \'Virginia\' adı kimi onurlandırır?', '\'Bakire Kraliçe\' diye anılan I. Elizabeth\'i', ['Raleigh\'in annesi Virginia\'yı', 'Antik Roma\'da Hristiyanlık uğruna şehit edilen azize Virginia\'yı', 'İspanya Kraliçesi Isabella\'yı'], 'Hiç evlenmeyen I. Elizabeth \'Virgin Queen\' diye anılıyordu; Roanoke\'taki ilk koloni denemesi başarısız oldu, kalıcı yerleşim 1607\'de Jamestown\'da kuruldu.'),
  ('I. Elizabeth\'in 1603\'te varis bırakmadan ölmesinin İngiltere ve İskoçya açısından sonucu hangisidir?', 'VI. James\'in İngiltere tahtına da çıkıp iki tacı birleştirmesi', ['İngiltere\'nin cumhuriyete dönüşmesi', 'Tahtın İspanya kralına geçmesi', 'İskoçya\'nın İngiltere\'ye savaş açması ve sınır kentlerini ele geçirmesi'], 'Mary Stuart\'ın oğlu VI. James, İngiltere\'de I. James adıyla tahta çıktı; iki krallığın parlamentoları ise 1707\'ye kadar ayrı kaldı.'),
  ('1605\'te bir grup Katoliğin, parlamentonun açılış günü kral ve milletvekilleriyle birlikte binayı havaya uçurma girişimi hangi adla bilinir?', 'Barut Komplosu', ['Rye House Komplosu', 'Babington Komplosu', 'Ridolfi Komplosu'], 'Guy Fawkes, Lordlar Kamarası\'nın altındaki mahzende barut fıçılarının başında yakalandı; 5 Kasım hâlâ İngiltere\'de kutlanır.'),
  ('I. James\'in desteğiyle hazırlanıp 1611\'de yayımlanan ve İngiliz dilini ve edebiyatını yüzyıllar boyunca derinden etkileyen eser hangisidir?', 'Kral James İncili', ['Ortak Dua Kitabı', 'Cenevre İncili', 'Westminster İtirafnamesi'], 'Kırk yedi bilginin hazırladığı bu çeviri (Authorized Version), İngilizce konuşulan Protestan dünyada en çok okunan metinlerden biri oldu.'),
  ('Parlamentonun 1628\'de I. Charles\'a kabul ettirdiği Hak Dilekçesi (Petition of Right) aşağıdaki ilkelerden hangisini içerir?', 'Parlamentonun onayı olmadan vergi alınamayacağı', ['Kralın kiliseyi yönetme yetkisinin kaldırıldığı', 'Ordunun yalnız parlamentoya bağlı olduğu', 'Bütün yetişkin erkeklerin oy kullanabileceği'], 'Hak Dilekçesi ayrıca sebepsiz tutuklamayı ve askerlerin evlere zorla yerleştirilmesini yasakladı; ancak Charles kısa süre sonra parlamentosuz yönetime geçti.'),
  ('İngiliz İç Savaşı\'nda kral yanlılarına ve parlamento yanlılarına verilen lakaplar sırasıyla hangisidir?', 'Kavalyeler ve Yuvarlak Kafalar', ['Whigler ve Toryler', 'Puritenler ve Kalvinistler', 'Jakobitler ve Hanoverciler'], 'Uzun saçlı soyluları anımsatan \'Kavalye\' kralcıları, kısa saçlı Londra çıraklarına gönderme yapan \'Yuvarlak Kafa\' ise parlamentocuları belirtiyordu.'),
  ('Parlamentonun 1645\'te kurduğu, terfinin soyluluğa değil yeteneğe dayandığı ve Naseby\'de kralcı orduyu yenen profesyonel ordu hangisidir?', 'Yeni Model Ordu', ['Eğitilmiş Bantlar', 'Kraliyet Muhafızları', 'Doğu Birliği Ordusu'], 'Thomas Fairfax ve Oliver Cromwell komutasındaki Yeni Model Ordu, disiplin ve dinî bağlılığıyla öne çıktı; sonradan siyasette de belirleyici güç oldu.'),
  ('İngiltere\'de 1660\'ta monarşinin yeniden kurulmasıyla tahta çıkan kral kimdir?', 'II. Charles', ['II. James', 'I. James', 'III. William'], 'Cromwell\'in ölümünden sonra yaşanan kargaşa, General Monck\'un desteğiyle sürgündeki II. Charles\'ın geri çağrılmasıyla sona erdi; bu döneme Restorasyon denir.'),
  ('1666\'da Londra\'nın büyük bölümünü yok eden yangından sonra kentin yeniden yapımında Aziz Paul Katedrali dahil pek çok kiliseyi tasarlayan mimar kimdir?', 'Christopher Wren', ['Inigo Jones', 'Nicholas Hawksmoor', 'John Vanbrugh'], 'Büyük Londra Yangını\'ndan sonra Wren, elliden fazla kilise ve yeni Aziz Paul Katedrali\'ni tasarladı.'),
  ('1679\'da İngiliz parlamentosunun çıkardığı ve tutuklanan bir kişinin yargıç önüne çıkarılmadan keyfî olarak hapiste tutulmasını önleyen yasa hangisidir?', 'Habeas Corpus Yasası', ['Sınav Yasası', 'Hoşgörü Yasası', 'Veraset Yasası'], 'Habeas corpus (\'bedeni getir\') ilkesi, tutuklamanın hukuki dayanağının bir yargıç önünde denetlenmesini güvenceye aldı.'),
  ('1689 Hoşgörü Yasası\'nın kapsamı en doğru biçimde hangisidir?', 'Anglikan olmayan Protestanlara ibadet özgürlüğü verip Katolikleri dışarıda bırakması', ['Bütün dinlere ve mezheplere tam eşitlik tanıması', 'Yalnız Katoliklere ibadet özgürlüğü tanıması', 'Anglikan Kilisesi\'ni kaldırıp devleti dinden ayırması ve bütün mezhepleri eşitlemesi ve korumaya alması'], 'Yasa, Presbiteryen, Baptist ve Quaker gibi Protestan \'muhaliflere\' kendi ibadethanelerinde dua etme hakkı verdi; ancak kamu görevleri onlara kapalı kaldı.'),
  ('1694\'te kurulan İngiltere Bankası\'nın ilk işlevi hangisidir?', 'Fransa\'ya karşı savaşlar için hükümete borç vermek', ['Kâğıt parayı yasaklayıp altın sikke basmak', 'Doğu Hindistan Şirketi\'nin hisselerini satmak ve kârını hükümetle paylaşmak', 'Köylülere düşük faizli tarım kredisi dağıtmak'], 'Banka, parlamentonun güvencesindeki uzun vadeli kamu borcunun temelini attı; bu \'mali devrim\' İngiltere\'nin savaş gücünü artırdı.'),
  ('1707 Birlik Yasası ile ortaya çıkan siyasi değişiklik hangisidir?', 'İngiltere ve İskoçya\'nın tek parlamentolu Büyük Britanya\'da birleşmesi', ['İrlanda\'nın İngiltere\'den ayrılarak bağımsız bir krallık olarak tanınması ve kendi kralını seçmesi', 'Galler\'in ilk kez İngiltere\'ye katılması', 'İngiltere\'nin Hanover ile tek bir devlet olması'], 'İki krallık 1603\'ten beri aynı hükümdara sahipti; 1707\'de parlamentolar da birleşti ve Büyük Britanya Krallığı kuruldu.'),
  ('1627-1628\'de Richelieu\'nün yönetiminde uzun bir kuşatmayla teslim alınan ve Hugenotların en önemli kalesi olan liman kenti hangisidir?', 'La Rochelle', ['Montauban', 'Nîmes', 'Bordeaux'], 'Kuşatmadan sonra 1629 Alès Barışı ile Hugenotlar din özgürlüklerini korudu ama güvenlik kentleri ve askerî ayrıcalıkları ellerinden alındı.'),
  ('Fransız dilini düzenlemek ve bir sözlük hazırlamak amacıyla 1635\'te Richelieu\'nün himayesinde kurulan kurum hangisidir?', 'Fransız Akademisi', ['Bilimler Akademisi', 'Sorbonne', 'Collège de France'], 'Académie française\'in kurulması, kültürü de merkezî otoriteye bağlama politikasının parçasıydı.'),
  ('XIV. Louis çocukken annesi Avusturyalı Anne\'ın naipliği döneminde Fransız yönetimini fiilen elinde tutan İtalyan asıllı kardinal kimdir?', 'Jules Mazarin', ['Armand de Richelieu', 'Jean-Baptiste Colbert', 'Nicolas Fouquet'], 'Richelieu\'nün yetiştirdiği Mazarin, 1661\'deki ölümüne kadar başbakanlık yaptı; Vestfalya ve Pireneler barışlarının mimarlarındandır.'),
  ('1648-1653 yılları arasında Paris Parlamentosu ve büyük soyluların kraliyet otoritesine karşı yürüttüğü ayaklanmalar dizisi hangi adla anılır?', 'Fronde', ['Jakerie', 'Ligue', 'Camisard'], 'Fronde, sapan anlamına gelir; ayaklanmaların sonunda soylular ve parlamento bölündü ve krallık otoritesi daha da güçlendi.'),
  ('XIV. Louis 1661\'de Kardinal Mazarin ölünce hangi kararı alarak devlet yönetimindeki tutumunu açıkça ortaya koymuştur?', 'Yeni bir başbakan atamayıp devlet işlerini bizzat yürütmek', ['Bütün yetkilerini annesine devredip ordusunun başında uzun bir sefere çıkmak', 'Etats Généraux\'yu her yıl toplamaya karar vermek', 'Papadan yeni bir başbakan atamasını istemek'], 'Louis bakanlarına artık her konuda doğrudan kendisine danışmalarını emretti; 1715\'teki ölümüne dek başbakan atamadı.'),
  ('XIV. Louis\'nin sarayını 1682\'de Paris\'ten Versay\'a taşımasının siyasi amacı en iyi hangi seçenekle açıklanır?', 'Büyük soyluları gözetim altında tutup krala bağımlı kılmak', ['Başkenti deniz kıyısına yaklaştırarak donanmayı ve deniz ticaretini güçlendirmek', 'Paris halkını yönetime daha fazla katmak', 'Saray masraflarını azaltarak hazineyi doldurmak'], 'Versay\'da yaşayan soylular, kralın uyanış ve yatış törenlerinde görev almak için yarıştı; böylece eyaletlerdeki bağımsız güçlerinden uzaklaştılar.'),
  ('XIV. Louis\'nin kendini Güneş ve tanrı Apollon simgeleriyle sunması hangi düşünceyi yansıtır?', 'Kralın devletin her şeyin çevresinde döndüğü merkezi olduğunu', ['Kralın yalnız tarım ve hasat işleriyle ilgilendiğini ve köylülerin koruyucusu olduğunu', 'Kralın pagan dinine geçmek istediğini', 'Kralın gücünü halk meclisiyle paylaştığını'], 'Güneş Kral imgesi saray törenlerinde, bale gösterilerinde ve Versay\'ın süslemelerinde sürekli kullanıldı; propaganda aracı olarak işlev gördü.'),
  ('XIV. Louis\'nin sarayında Molière\'in oyunları ve Lully\'nin müzikleriyle sanatın desteklenmesi mutlakiyet açısından hangi işlevi görmüştür?', 'Kralın ihtişamını yücelten bir propaganda aracı olması', ['Kralın gücünü eleştiren muhalefetin sesini yükseltmesi ve sansürü zayıflatması', 'Sanatın kiliseye bağımlı kalmasını sağlaması', 'Halkın saraydan tümüyle uzak tutulmasını sağlaması'], 'Akademiler, saray gösterileri ve maaş bağlanan sanatçılar, \'büyük yüzyıl\' kültürünü kralın şanıyla özdeşleştirdi.'),
  ('İspanya Veraset Savaşı\'nın başlamasına yol açan gelişme hangisidir?', 'II. Carlos\'un tahtı XIV. Louis\'nin torunu Philippe\'e vasiyet etmesi', ['V. Karl\'ın tahttan çekilerek topraklarını paylaştırması', 'Avusturya imparatorunun bir oğul bırakmadan ölmesi ve tahtın kızına geçmesinin tartışılması', 'İngiltere\'de I. Charles\'ın idam edilmesi'], 'Fransa ve İspanya\'nın aynı hanedanın elinde birleşmesi korkusu İngiltere, Hollanda ve Avusturya\'yı Büyük İttifak\'ta bir araya getirdi.'),
  ('XIV. Louis\'nin tahtta kaldığı süre (1643-1715) Avrupa tarihinin en uzun hükümdarlıkları arasındadır. Bu süre kaç yıldır?', '72 yıl', ['54 yıl', '63 yıl', '81 yıl'], '1715 - 1643 = 72. Louis dört yaşında tahta çıktı ve uzun ömrü boyunca oğlunu ve torununu kaybetti; yerine beş yaşındaki torununun oğlu XV. Louis geçti.'),
  ('1618\'de Prag\'da Protestan soyluların imparatorluk temsilcilerini şatonun penceresinden aşağı atması olayı hangi adla bilinir?', 'Prag Defenestrasyonu', ['Prag Baharı', 'Prag Barışı', 'Prag Bildirisi'], 'Pencereden atılan temsilciler yaralı olarak kurtuldu; olay Bohemya isyanını ve Otuz Yıl Savaşları\'nı başlattı.'),
  ('Otuz Yıl Savaşları\'nda imparator adına büyük bir paralı ordu kurup bu orduyu işgal edilen bölgelerden toplanan zorunlu katkılarla besleyen, sonra 1634\'te suikastla öldürülen komutan kimdir?', 'Albrecht von Wallenstein', ['Johann Tserclaes von Tilly', 'Gottfried zu Pappenheim', 'Ottavio Piccolomini'], 'Wallenstein\'ın \'savaş savaşı besler\' anlayışı orduyu büyüttü; ancak artan gücü imparatoru kuşkulandırdı ve öldürülmesine onay verildi.'),
  ('1630\'da Almanya\'ya çıkarma yaparak Otuz Yıl Savaşları\'na giren, Breitenfeld\'de büyük bir zafer kazanıp 1632\'de Lützen\'de ölen İsveç kralı kimdir?', 'II. Gustav Adolf', ['X. Karl Gustav', 'XII. Karl', 'I. Gustav Vasa'], 'Gustav Adolf\'un hafif toplar ve esnek piyade düzeniyle yaptığı reformlar onu \'Kuzeyin Aslanı\' yaptı; ölümü İsveç\'in savaştaki ilerleyişini yavaşlattı.'),
  ('1631\'de Tilly komutasındaki imparatorluk ordusunun bir Protestan kentini alıp yaklaşık yirmi bin kişiyi öldürmesi ve kenti yakması, savaşın en büyük vahşetlerinden biri olarak anılır. Bu kent hangisidir?', 'Magdeburg', ['Leipzig', 'Nördlingen', 'Augsburg'], 'Magdeburg\'un yıkılışı Protestan dünyasını sarstı; \'Magdeburglaştırmak\' deyimi topyekûn yıkım anlamında kullanıldı.'),
  ('Fransa\'nın 1635\'te Otuz Yıl Savaşları\'na doğrudan Habsburglara karşı girmesi savaşın niteliği hakkında neyi gösterir?', 'Savaşın din çatışmasından devletler arası güç mücadelesine dönüştüğünü', ['Fransa\'nın Protestanlığa geçtiğini ve Katolik dünyasından ayrıldığını', 'Savaşın yalnız Alman prensleri arasında bir iç savaş olarak kaldığını', 'Papanın Fransa\'ya Habsburglara saldırması için emir verdiğini'], 'Katolik Fransa\'nın Katolik Habsburglara karşı Protestan İsveç\'in yanında savaşması, savaşın son evresinde dinin değil hanedan ve devlet çıkarının belirleyici olduğunu gösterir.'),
  ('1648 Vestfalya Barışı\'yla bağımsızlıkları uluslararası düzeyde resmen tanınan iki devlet hangileridir?', 'Hollanda ve İsviçre', ['Portekiz ve Katalonya Prensliği', 'Bohemya ve Macaristan', 'Prusya ve Saksonya'], 'Hollanda\'nın bağımsızlığını İspanya Münster\'de kabul etti; İsviçre\'nin imparatorluktan fiilen ayrılmışlığı da hukuken onaylandı.'),
  ('1659\'da Fransa ile İspanya arasında imzalanan ve XIV. Louis\'nin İspanyol prensesi Maria Teresa ile evlenmesini de öngören antlaşma hangisidir?', 'Pireneler Antlaşması', ['Vestfalya Antlaşması', 'Nijmegen Antlaşması', 'Aix-la-Chapelle Antlaşması'], 'Otuz Yıl Savaşları\'ndan sonra da süren Fransız-İspanyol savaşını bitiren bu antlaşmayla Fransa, Roussillon ve Artois\'yı aldı.'),
  ('I. Maximilian ve torunlarının yaptığı stratejik evlilikler Habsburglara geniş topraklar kazandırmıştır. Bu politikayı özetleyen \'Bırak başkaları savaşsın, sen mutlu Avusturya, evlen\' sözü neyi vurgular?', 'Topraklarını savaştan çok evlilik ittifaklarıyla genişletmesini', ['Avusturya\'nın hiçbir zaman savaşa girmediğini ve tarafsız kaldığını', 'Habsburg prenslerinin evlenmesinin kilisece yasaklanmasını', 'Avusturya\'nın topraklarını yalnız satın alarak büyüttüğünü'], 'Maximilian\'ın Burgonyalı Mary ile evliliği Felemenk\'i, oğlunun Juana ile evliliği İspanya\'yı, 1515 Viyana anlaşmaları ise Bohemya ve Macaristan\'ı Habsburglara getirdi.'),
  ('I. Maximilian\'ın 1477\'de evlenerek Habsburglara Felemenk dahil zengin toprakları kazandırdığı varis prenses kimdir?', 'Burgonyalı Mary', ['Kastilyalı Juana', 'Bretanyalı Anne', 'Avusturyalı Margarethe'], 'Cesur Charles\'ın tek kızı olan Mary\'nin mirası, Habsburgları Fransa ile uzun bir rekabete soktu.'),
  ('II. Joseph\'in 1781\'de yayımladığı Hoşgörü Fermanı ile aşağıdakilerden hangisi gerçekleşmiştir?', 'Lutherci, Kalvinist ve Ortodokslara ibadet hakkı tanınması', ['Katolikliğin Avusturya\'da tümüyle yasaklanması', 'Bütün manastırların sayısının iki katına çıkarılması ve yeni tarikatlar kurulması', 'Yahudilerin imparatorluktan sürülmesi'], 'Ferman, Katolik olmayan Hristiyanlara ibadet ve kamu görevi hakları verdi; ertesi yıl Yahudilere yönelik bir hoşgörü fermanı da çıkarıldı.'),
  ('1628\'de Stockholm limanında ilk yolculuğuna çıkar çıkmaz devrilip batan, 1961\'de çıkarılarak bugün müzede sergilenen İsveç savaş gemisinin adı nedir?', 'Vasa', ['Kronan', 'Mary Rose', 'Victory'], 'Ağır top güvertesi nedeniyle dengesiz olan Vasa birkaç yüz metre ilerleyince battı; soğuk ve az tuzlu Baltık suyu gövdenin büyük ölçüde korunmasını sağladı.'),
  ('1654\'te tahttan feragat edip Katolikliğe geçen ve hayatının geri kalanını Roma\'da geçiren, Descartes\'ı da sarayına davet etmiş olan İsveç kraliçesi kimdir?', 'Kristina', ['Ulrika Eleonora', 'Margrethe', 'Hedvig Eleonora'], 'Gustav Adolf\'un kızı Kristina\'nın Lutherci bir krallıkta Katolikliğe geçmesi tahtı bırakmasını zorunlu kıldı; Descartes onun sarayında 1650\'de öldü.'),
  ('Büyük Kuzey Savaşı\'nın başında, 1700\'de genç XII. Karl\'ın sayıca çok üstün Rus ordusunu yendiği savaş hangisidir?', 'Narva Savaşı', ['Lützen Savaşı', 'Breitenfeld Savaşı', 'Fraustadt Savaşı'], 'Narva yenilgisi I. Petro\'yu orduyu baştan düzenlemeye yöneltti; dokuz yıl sonra Rusya, Poltava\'da rövanşı aldı.'),
  ('Moskova hükümdarlarının 16. yüzyılda resmî olarak kullanmaya başladığı \'çar\' unvanının kökeni hangisidir?', 'Roma\'daki \'Caesar\' unvanı', ['Moğol hanlarının kullandığı \'kağan\' unvanı', 'Bizans\'taki \'basileus\' unvanının Slavca çevirisi', 'Vikinglerin kullandığı \'konung\' unvanı'], 'Çar sözcüğü Latince Caesar\'dan, Slav dillerindeki \'tsesar\' biçimi üzerinden gelir; Almancadaki Kaiser unvanı da aynı köktendir.'),
  ('Moskova\'daki renkli soğan kubbeleriyle tanınan Aziz Vasili Katedrali hangi askerî başarının anısına yaptırılmıştır?', 'Kazan Hanlığı\'nın 1552\'de fethedilmesi', ['Poltava\'da İsveçlilerin yenilmesi', 'Napolyon\'un Moskova\'dan çekilmesi', 'Polonyalıların Moskova\'dan atılması'], 'IV. İvan\'ın Kazan\'ı alması, Rusya\'nın Volga boyunca güneye ve doğuya genişlemesinin önünü açtı; katedral bu zaferi anmak için Kızıl Meydan\'a yapıldı.'),
  ('I. Petro\'nun 1697-1698\'de kimliğini gizleyerek Hollanda ve İngiltere tersanelerinde çalıştığı Batı Avrupa gezisi hangi adla bilinir?', 'Büyük Elçilik', ['Kutsal İttifak', 'Kuzey Seferi', 'Yeni Model Ordu'], 'Petro, gemi yapımını ve Batı teknolojisini yerinde öğrendi; gezisi Streltsi isyanı haberiyle yarıda kaldı.'),
  ('I. Petro\'nun Rus Ortodoks Kilisesi\'nde patrikliği kaldırıp yerine devlete bağlı bir kurul (Kutsal Sinod) kurmasının amacı hangisidir?', 'Kiliseyi çarın denetimine alıp bağımsız bir güç olmasını önlemek', ['Rus Kilisesi\'ni Katolik Kilisesi\'ne bağlamak, papayı tanımak ve Latin ayinini getirmek', 'Kiliseye devletten bağımsız yeni ayrıcalıklar tanımak', 'Ortodoksluğu yasaklayıp Lutherciliği resmî din yapmak'], 'Sinod\'un başında çarın atadığı bir sivil görevli (başsavcı) bulunuyordu; kilise fiilen bir devlet dairesine dönüştü.'),
  ('1773-1775\'te kendini öldürülen çar III. Petro olarak tanıtan bir Kazak\'ın önderliğinde Volga ve Ural bölgesinde çıkan büyük köylü-Kazak ayaklanması hangisidir?', 'Pugaçev İsyanı', ['Razin İsyanı', 'Bulavin İsyanı', 'Dekabrist İsyanı'], 'Pugaçev İsyanı bastırıldıktan sonra II. Katerina soylularla ittifakını güçlendirdi ve serflerin durumu daha da ağırlaştı.'),
  ('Büyük Seçici\'nin 1685\'te yayımladığı Potsdam Fermanı\'nın amacı hangisidir?', 'Fransa\'dan kaçan Hugenotları Brandenburg\'a yerleşmeye davet etmek', ['Brandenburg\'daki bütün Katolikleri sürgün etmek ve topraklarını dağıtmak', 'İsveç\'e savaş ilan ederek Pomeranya\'yı ele geçirmek', 'Prusya\'yı Polonya krallığına tamamen bağlamak ve vergi ödemek'], 'Fontainebleau Fermanı\'na yanıt olan bu belge, göçmenlere vergi muafiyeti ve din özgürlüğü tanıdı; yaklaşık yirmi bin Hugenot geldi ve Berlin\'in ekonomisini canlandırdı.'),
  ('II. Friedrich\'in 1740\'ta tahta çıkar çıkmaz Habsburglardan aldığı ve Prusya\'nın nüfusunu ve sanayisini büyük ölçüde artıran zengin eyalet hangisidir?', 'Silezya', ['Bohemya', 'Saksonya', 'Pomeranya'], 'Silezya\'nın alınması Avusturya Veraset Savaşı\'nı başlattı; Maria Theresia bu eyaleti geri almak için yıllarca uğraştı ama başaramadı.'),
  ('II. Friedrich\'in Potsdam\'da yaptırdığı ve adı Fransızca \'kaygısız\' anlamına gelen yazlık sarayı hangisidir?', 'Sanssouci', ['Charlottenburg', 'Schönbrunn', 'Nymphenburg'], 'Friedrich burada flüt çalar, Voltaire gibi düşünürlerle sohbet ederdi; sarayın adı hükümdarın kişisel dinlenme yeri olma işlevini yansıtır.'),
  ('II. Friedrich\'in Prusya\'da yoksul halkın beslenmesini iyileştirmek için kararnamelerle ekimini yaygınlaştırmaya çalıştığı Amerika kökenli ürün hangisidir?', 'Patates', ['Mısır', 'Tütün', 'Domates'], '1756\'daki \'patates emri\' gibi kararnameler, kıtlıklara karşı dayanıklı bir besin kaynağı oluşturmayı amaçlıyordu.'),
  ('1569 Lublin Birliği ile ortaya çıkan siyasi yapı hangisidir?', 'Polonya ile Litvanya\'nın ortak meclisli tek bir devlette birleşmesi', ['Polonya\'nın Rusya ile birleşerek tek bir çarlık oluşturması ve Moskova\'nın başkent olması', 'Litvanya\'nın Polonya\'dan tümüyle ayrılarak İsveç\'e katılması', 'Polonya\'nın Habsburg İmparatorluğu\'na bağlanması'], 'Daha önce yalnız aynı hükümdarı paylaşan iki devlet, ortak bir kral seçimi ve ortak Sejm ile \'İki Ulus Cumhuriyeti\'ni oluşturdu.'),
  ('Polonya-Litvanya meclisinde tek bir milletvekilinin itirazıyla kararların engellenip oturumun dağıtılabilmesine olanak veren ilke hangisidir?', 'Liberum veto', ['Habeas corpus', 'Cuius regio, eius religio', 'Raison d\'État'], 'Soyluların eşitliğini koruma amacı taşıyan liberum veto, 17. ve 18. yüzyılda yabancı devletlerin rüşvetle meclisi felç etmesine yol açtı.'),
  ('1573 Varşova Konfederasyonu\'nun Avrupa tarihindeki önemi hangisidir?', 'Farklı Hristiyan mezheplerine din özgürlüğü güvencesi vermesi', ['Polonya\'da Katolikliği tek din ilan edip Protestanları ve Ortodoksları ülkeden sürmesi', 'Polonya\'yı Osmanlı\'ya karşı bir Haçlı ittifakına sokması', 'Kralın yetkilerini mutlak hâle getirmesi'], 'Din savaşlarının yaşandığı bir Avrupa\'da Polonya-Litvanya, farklı mezheplerin barış içinde yaşamasını hukuken güvenceye aldı.'),
  ('Tirol ve Macaristan\'daki gümüş ve bakır madenlerini işleterek Avrupa\'nın en zengin bankerlerinden biri olan, imparatorlara ve papalara borç veren Augsburglu tüccar kimdir?', 'Jakob Fugger', ['Cosimo de\' Medici', 'Anton Welser', 'Jacques Cœur'], '\'Zengin\' lakaplı Jakob Fugger\'in kredileri V. Karl\'ın imparator seçilmesinde belirleyici oldu; aile maden tekelleriyle büyük servet kazandı.'),
  ('1487\'de Heinrich Kramer\'in yazdığı ve cadıları tanıma, sorgulama ve cezalandırma konusunda el kitabı olarak kullanılan eser hangisidir?', 'Malleus Maleficarum', ['Summa Theologica', 'Index Librorum Prohibitorum', 'Corpus Juris Civilis'], '\'Cadıların Çekici\' adlı bu kitap, matbaa sayesinde çok sayıda baskı yaparak cadı kovuşturmalarına kuramsal dayanak sağladı.'),
  ('Thomas More\'un \'Ütopya\'da \'koyunlar insanları yiyor\' diyerek eleştirdiği İngiltere\'deki gelişme hangisidir?', 'Ortak tarlaların yün üretimi için çitle çevrilip köylülerin çıkarılması', ['Koyun vebasının bütün ülkeye yayılması ve hastalığın insanlara da bulaşarak köyleri boşaltması', 'Kralın bütün koyunlara el koyarak orduyu beslemesi', 'Köylülerin et tüketimini yasaklayan dinî kurallar'], 'Yün ticaretinin kârlılığı toprak sahiplerini tarlaları otlağa çevirmeye yöneltti; çitleme (enclosure) pek çok köylü ailesini topraksız bıraktı.'),
  ('Yaklaşık 14. yüzyıldan 19. yüzyıla kadar süren ve özellikle 17. yüzyılda kötü hasatlara, kıtlıklara ve salgınlara katkıda bulunan iklim soğumasına verilen ad hangisidir?', 'Küçük Buzul Çağı', ['Orta Çağ Sıcak Dönemi', 'Holosen İklim Optimumu', 'Pleistosen Buzullaşması'], 'Soğuk ve yağışlı yıllar ürünleri azalttı; tarihçiler 17. yüzyılın \'genel kriz\'inde bu iklim etkisini de önemli bir etken sayar.'),
  ('Montesquieu\'nün 1748\'de yayımlanan \'Kanunların Ruhu\' adlı eserinde özgürlüğü korumak için önerdiği ilke hangisidir?', 'Yasama, yürütme ve yargı güçlerinin ayrı ellerde bulunması', ['Bütün yetkilerin aydınlanmış ve eğitimli tek bir hükümdarda toplanması', 'Kilisenin devlet işlerinde son sözü söylemesi', 'Mülkiyetin kaldırılıp toprağın ortak işlenmesi'], 'Montesquieu, İngiliz düzenini örnek alarak güçlerin birbirini dengelemesini savundu; bu ilke sonraki anayasaları derinden etkiledi.'),
  ('Voltaire\'in 1762\'de oğlunu öldürmekle haksız yere suçlanıp idam edilen Protestan tüccar Jean Calas için yürüttüğü kampanya hangi değeri savunmanın simgesi olmuştur?', 'Dinî hoşgörü ve adil yargılanma hakkını', ['Kralın mutlak yetkisini ve ilahi hakkını', 'Soyluların vergi muafiyetini ve ayrıcalıklarını', 'Engizisyon mahkemelerinin yeniden kurulmasını'], 'Voltaire\'in \'Hoşgörü Üzerine İnceleme\'si ve kamuoyu baskısı sonucunda Calas ölümünden sonra aklandı.'),
  ('Cesare Beccaria\'nın 1764\'te yayımlanan \'Suçlar ve Cezalar Üzerine\' adlı eserinin ceza hukukuna getirdiği temel öneri hangisidir?', 'İşkencenin kaldırılması ve cezaların suçla orantılı olması', ['Suçluların ailelerinin de aynı biçimde cezalandırılarak caydırıcılığın artırılması', 'Cezaların yalnız kilise mahkemelerince verilmesi', 'Bütün suçlar için ölüm cezasının uygulanması'], 'Beccaria, cezanın amacının intikam değil suçun önlenmesi olduğunu savundu; Toskana 1786\'da ölüm cezasını kaldıran ilk devletlerden oldu.'),
  ('Immanuel Kant\'ın 1784 tarihli \'Aydınlanma Nedir?\' yazısında Aydınlanma\'nın parolası olarak önerdiği Latince söz hangisidir?', 'Sapere aude (Bilmeye cesaret et)', ['Cogito ergo sum (Düşünüyorum öyleyse varım)', 'Carpe diem (Günü yakala)', 'Memento mori (Öleceğini unutma)'], 'Kant\'a göre Aydınlanma, insanın kendi aklını başkasının yönlendirmesi olmadan kullanma cesaretiyle \'kendi suçu olan ergin olmayış\'tan çıkmasıdır.'),
  ('François Quesnay\'nin önderlik ettiği fizyokratlara göre bir ülkenin gerçek zenginlik kaynağı hangisidir?', 'Toprak ve tarım', ['Biriktirilen altın ve gümüş', 'Dış ticaret fazlası', 'Sömürgelerden alınan vergiler'], 'Fizyokratlar yalnız toprağın net ürün yarattığını savundu ve merkantilist kısıtlamalara karşı \'bırakınız yapsınlar\' anlayışıyla serbest ticareti önerdi.'),
  ('18. yüzyıl Paris\'inde Madame Geoffrin gibi kadınların evlerinde düzenlediği ve yazar, bilim insanı ve soyluları bir araya getiren toplantılar Aydınlanma\'nın yayılmasında hangi işlevi görmüştür?', 'Fikirlerin tartışılıp dolaştığı bir sohbet ortamı yaratmak', ['Kilisenin vaazlarını halka ulaştırmak ve dinî kuralların uygulanmasını denetlemek', 'Kralın kararnamelerini soylulara resmen tebliğ etmek', 'Askerî stratejilerin gizlice planlanmasını sağlamak'], 'Salonlar, kahvehaneler ve akademilerle birlikte, Aydınlanma düşüncesinin tartışıldığı yeni bir kamusal alanın parçasıydı.'),
  ('Aydın despotlar olarak anılan II. Friedrich, II. Joseph ve II. Katerina\'nın ortak yönü en iyi hangi seçenekte ifade edilir?', 'Aydınlanma esinli reformları mutlak yetkilerini koruyarak yukarıdan uygulamaları', ['Yetkilerini seçilmiş meclislere devrederek anayasal monarşi kurmaları ve basını serbest bırakmaları', 'Kiliseye bütün devlet yönetimini bırakmaları', 'Reform yapmayı reddedip yalnız savaşla uğraşmaları'], 'Bu hükümdarlar hukuk, eğitim, din hoşgörüsü ve yönetimde akılcı düzenlemeler yaptı; ancak siyasi katılım genişletilmedi.'),
  ('1607\'de Mantova sarayında sahnelenen ve opera türünün ilk büyük başyapıtı sayılan \'L\'Orfeo\'nun bestecisi kimdir?', 'Claudio Monteverdi', ['Jacopo Peri', 'Giovanni Pierluigi da Palestrina', 'Antonio Vivaldi'], 'Opera 1600 dolaylarında Floransa\'da antik Yunan tragedyasını canlandırma çabasıyla doğdu; Monteverdi bu yeni türü zengin bir müzik diliyle olgunlaştırdı.'),
  ('Rembrandt\'ın 1642 tarihli ve Amsterdam\'daki bir sivil muhafız birliğini hareket hâlinde gösteren büyük grup portresi hangi adla tanınır?', 'Gece Devriyesi', ['Anatomi Dersi', 'Müsrif Oğlun Dönüşü', 'Kumaşçılar Loncası Yöneticileri'], 'Eserin adı, zamanla koyulaşan vernik nedeniyle sahnenin gece sanılmasından gelir; aslında sahne gündüz geçmektedir.'),
  ('Aziz Petrus Bazilikası\'nın önündeki ve kucaklayan kollar gibi meydanı çevreleyen büyük sütunlu revakları tasarlayan Barok sanatçı kimdir?', 'Gian Lorenzo Bernini', ['Francesco Borromini', 'Carlo Maderno', 'Pietro da Cortona'], 'Bernini\'nin revakları kilisenin inananları kucaklayışını simgeler; bazilika içindeki bronz baldaken de onun eseridir.'),
  ('İtalyan sanat tarihinde \'Quattrocento\' terimi hangi dönemi anlatır?', '1400\'lü yılları', ['1300\'lü yılları', '1500\'lü yılları', '1600\'lü yılları'], 'İtalyanca \'dört yüz\' anlamındaki Quattrocento, \'bin dört yüzler\' demektir ve Erken Rönesans\'ı karşılar; 1500\'ler ise Cinquecento\'dur.'),
  ('Ceneviz Cumhuriyeti\'nin 1528\'de Fransa\'dan ayrılıp İmparator V. Karl\'ın tarafına geçmesini sağlayan ünlü amiral kimdir?', 'Andrea Doria', ['Marcantonio Colonna', 'Francesco Morosini', 'Sebastiano Venier'], 'Andrea Doria\'nın taraf değiştirmesi Ceneviz\'i İspanya\'nın Akdeniz\'deki müttefiki ve bankeri yaptı; kendisi de kentin fiilî yöneticisi oldu.'),
  ('Cromwell döneminde 1651\'de çıkarılan Seyrüsefer Yasası hangi ülkenin ticaretini doğrudan hedef almıştır?', 'Hollanda', ['Fransa', 'İspanya', 'Portekiz'], 'Yasa, İngiltere\'ye gelecek malların İngiliz gemileriyle ya da üretici ülkenin gemileriyle taşınmasını şart koşarak Hollanda\'nın aracı taşımacılığını kısıtladı.'),
  ('Bir tarihçi şu bilgileri sıralıyor: kalıcı bir ordu, merkeze bağlı memurlar, temsilî meclislerin zayıflaması ve sarayda toplanan soylular. Bu özellikler en çok hangi yönetim anlayışını tanımlar?', 'Mutlak monarşi', ['Feodal monarşi', 'Anayasal monarşi', 'Kent cumhuriyeti'], 'Erken modern mutlakiyet; sürekli ordu, bürokrasi ve soyluların krala bağlanmasıyla Orta Çağ\'ın parçalı feodal düzeninden ayrılır.'),
  ('Padua\'daki Scrovegni Şapeli fresklerinde figürlere hacim ve duygu kazandırarak Bizans üslubundan uzaklaşan ve Vasari\'nin Rönesans\'ın öncüsü saydığı 14. yüzyıl ressamı kimdir?', 'Giotto di Bondone', ['Duccio di Buoninsegna', 'Simone Martini', 'Cimabue'], 'Giotto\'nun gerçekçi beden ve jestleri, bir yüzyıl sonraki Masaccio gibi ressamlara örnek oldu; bu yüzden Rönesans\'ın habercisi sayılır.'),
  ('Luther\'in 1529\'da papazlar kadar aile reislerinin de çocuklarına inancın temel ilkelerini soru-cevap biçiminde öğretmesi için yazdığı kısa eser hangisidir?', 'Küçük İlmihal', ['Doksan Beş Tez', 'Augsburg İtirafnamesi', 'Bir Hristiyanın Özgürlüğü'], 'Luther, kiliseleri denetlerken halkın ve papazların dinî bilgisinin çok zayıf olduğunu gördü; Küçük İlmihal evlerde dinî eğitimin temel kitabı oldu.'),
  ('I. Elizabeth döneminde Anglikan Kilisesi\'ni Katolik kalıntılardan daha da arındırmak, piskoposluğu ve törenleri sadeleştirmek isteyen Kalvinist eğilimli gruplara ne ad verilmiştir?', 'Püritenler', ['Lollardlar', 'Anabaptistler', 'Jakobitler'], 'Püritenler, kilisenin \'saflaştırılması\' (purify) gerektiğini savundu; 17. yüzyılda parlamento muhalefetinde ve İç Savaş\'ta önemli rol oynadılar.'),
  ('Keşif çağında uzun okyanus yolculuklarında denizcilerin diş eti kanaması, halsizlik ve ölümle sonuçlanan bir hastalığa yakalanmasının nedeni hangisidir?', 'C vitamini yetersizliği', ['Tuzlu deniz suyunun içme suyuna karışması', 'Güneş ışığına uzun süre maruz kalınması', 'Gemilerdeki farelerin taşıdığı veba mikrobunun mürettebata bulaşması'], 'İskorbüt, Vasco da Gama ve Magellan seferlerinde de mürettebatın büyük kısmını öldürdü; turunçgillerin koruyucu etkisi ancak 18. yüzyılda sistemli olarak kanıtlandı.'),
  ('VIII. Henry\'nin donanmasının gözde gemisi olan ve 1545\'te Fransızlara karşı bir çatışma sırasında batan, 1982\'de denizden çıkarılan gemi hangisidir?', 'Mary Rose', ['Golden Hind', 'Henry Grace à Dieu', 'Ark Royal'], 'Mary Rose\'un enkazı, Tudor dönemi denizcilerinin silahları, giysileri ve gündelik eşyaları hakkında eşsiz bilgiler sağladı.'),
  ('Eski rejim Fransa\'sında köylülerin ve kentlilerin ödediği, soyluların ve din adamlarının ise büyük ölçüde muaf tutulduğu başlıca doğrudan vergi hangisidir?', 'Taille', ['Gabelle', 'Ondalık', 'Kapitülasyon'], 'Taille\'ın yükü en yoksul kesimlerin omzundaydı; ayrıcalıklıların muafiyeti mutlak monarşinin mali sorunlarının kökenlerinden biriydi.'),
  ('XIV. Louis\'nin yaralı ve yaşlı askerler için Paris\'te yaptırdığı, bugün Napolyon\'un mezarını da barındıran büyük yapı kompleksi hangisidir?', 'Les Invalides', ['Louvre', 'Palais-Royal', 'Tuileries'], 'Hôtel des Invalides, devletin kendi askerine bakma sorumluluğunu üstlendiğini gösteren ve sürekli ordunun önemini yansıtan bir yapıydı.'),
  ('1587\'de Cádiz limanına baskın düzenleyip Armada için hazırlanan çok sayıda gemiyi ve erzakı yok eden, bu eylemini \'İspanya kralının sakalını yakmak\' diye anlatan İngiliz kimdir?', 'Francis Drake', ['John Hawkins', 'Walter Raleigh', 'Charles Howard'], 'Cádiz baskını İspanyol saldırısını yaklaşık bir yıl geciktirdi; Drake ertesi yıl Armada\'ya karşı da savaştı.'),
  ('Armada tehlikesi sırasında 1588\'de Tilbury\'de askerlerine seslenen I. Elizabeth\'in konuşmasında vurguladığı düşünce hangisidir?', 'Kadın bedenine karşın bir kralın yüreğine sahip olduğu', ['Tahtı İspanya kralıyla paylaşmaya hazır olduğu', 'Savaşı kaybetmeleri hâlinde Katolikliğe geçeceği', 'Askerlere hiçbir ücret ödenmeyeceği ve yalnız gönüllülük ve inanç için savaşmaları gerektiği'], 'Elizabeth \'zayıf ve güçsüz bir kadının bedenine sahibim ama bir kralın, hem de bir İngiltere kralının yüreği ve midesi bende\' diyerek askerlerin moralini yükseltti.'),
  ('Lutherci ve Kalvinist bölgelerde zamanla okuryazarlığın Katolik bölgelere göre daha hızlı artma eğilimi göstermesi en çok hangi öğretiyle ilişkilendirilir?', 'Her inananın Kutsal Kitap\'ı kendisinin okuması gerektiği düşüncesi', ['Ayinlerin yalnız Latince yapılması zorunluluğu', 'Din adamlarının evlenmesinin yasaklanması ve manastırların çoğaltılması', 'İmgelerin kiliselerde çoğaltılması'], 'Kutsal Kitap\'ı doğrudan okuma idealinin yanı sıra ilmihal eğitimi ve kilise okulları da Protestan bölgelerde okuma becerisini yaydı.'),
  ('Amsterdam\'daki Yahudi cemaatinden 1656\'da aforoz edilen ve 1670\'teki \'Teolojik-Politik İnceleme\'sinde düşünce ve ifade özgürlüğünü savunan filozof kimdir?', 'Baruch Spinoza', ['René Descartes', 'Pierre Bayle', 'Hugo Grotius'], 'Spinoza, kutsal metinlerin tarihsel olarak incelenmesini ve devletin düşünce özgürlüğünü koruması gerektiğini savundu; eser kısa sürede yasaklandı.'),
  ('Girit doğumlu olup Toledo\'ya yerleşen, uzatılmış figürleri ve canlı renkleriyle İspanyol dinî resminde eşsiz bir üslup yaratan ressam kimdir?', 'El Greco', ['Francisco de Zurbarán', 'Bartolomé Esteban Murillo', 'Jusepe de Ribera'], 'Asıl adı Domenikos Theotokopoulos olan El Greco, Bizans ikona geleneği ile Venedik resim tekniğini birleştirdi; \'Kont Orgaz\'ın Gömülmesi\' en ünlü eserlerindendir.'),
  ('16. ve 17. yüzyıllarda İspanya\'da Cervantes, Lope de Vega, Velázquez ve El Greco gibi isimlerin yetiştiği edebiyat ve sanat döneminin adı nedir?', 'Siglo de Oro (Altın Çağ)', ['Reconquista (Yeniden Fetih)', 'Risorgimento (Diriliş)', 'Belle Époque (Güzel Dönem)'], 'İspanya\'nın siyasi ve mali sıkıntılarına rağmen bu dönem kültürel üretim açısından çok verimliydi.'),
  ('Rönesans hakkında öne sürülen aşağıdaki yargılardan hangisi tarihsel olarak savunulamaz?', 'Rönesans\'ta dinî konulu sanat tümüyle terk edilmiştir', ['Rönesans sanatçıları antik eserleri inceleyip örnek almıştır', 'Rönesans hamileri arasında papalar ve kardinaller de vardır', 'Rönesans\'ta perspektif ve anatomi bilgisi resme uygulanmıştır'], 'Michelangelo\'nun Sistina freskleri ve sayısız sunak resmi gibi, Rönesans\'ın en ünlü eserlerinin büyük kısmı dinî konuludur; değişen, konuların işleniş biçimidir.'),
  ('Rönesans\'ta sanatçıların eserlerini imzalaması, kendi portrelerini yapması ve hayatlarının biyografilere konu olması hangi gelişmeyi yansıtır?', 'Sanatçının bireysel kimliğinin ve yaratıcılığının önem kazanmasını', ['Sanatın tümüyle anonim bir zanaata dönüşmesini', 'Sanatçıların loncalardan atılmasını', 'Kilisenin sanatçılara imza atmayı zorunlu kılmasını'], 'Orta Çağ\'da eserlerin çoğu anonimken Rönesans\'ta sanatçı ünlü bir birey ve \'dâhi\' olarak görülmeye başlandı.'),
  ('Bir resimde zemin döşemelerinin ve bina kenarlarının çizgileri, ufuk hizasındaki tek bir noktada birleşecek biçimde çizilmiştir. Ressam hangi tekniği kullanmıştır?', 'Tek kaçış noktalı doğrusal perspektif', ['Atmosferik (hava) perspektif', 'Ters perspektif', 'Önem perspektifi'], 'Doğrusal perspektifte birbirine paralel çizgiler göz hizasındaki bir kaçış noktasında birleşir; hava perspektifi ise uzaklığı renk ve netlik azalmasıyla gösterir.'),
  ('Bir sınav sorusunda \'16. yüzyılın ortasında yaşamış bir Avrupalı\' olarak tanıtılan bir kişinin aşağıdaki olaylardan hangisine kendi gözüyle tanık olması mümkün değildir?', 'Vestfalya Barışı\'nın imzalanması', ['Trento Konsili\'nin toplanması', 'Augsburg Barışı\'nın imzalanması', 'V. Karl\'ın tahttan çekilmesi'], 'Trento Konsili 1545-1563, Augsburg Barışı 1555, V. Karl\'ın çekilmesi 1556\'dır; Vestfalya ise 1648\'dedir ve yaklaşık bir asır sonradır.'),
  ('1530\'larda Saksonya\'da bir köy kilisesini denetleyen görevli şunları not ediyor: Papaz evli, ayin Almanca yapılıyor, endüljans satılmıyor ve cemaate ilmihal öğretiliyor. Bu kilise büyük olasılıkla hangi mezhebe bağlıdır?', 'Lutherci', ['Katolik', 'Anglikan', 'Ortodoks'], 'Saksonya Lutherciliğin doğduğu bölgedir; evli papaz, Almanca ayin ve endüljansın reddi Lutherci uygulamanın belirgin özellikleridir.'),
  ('Bir kentte kiliselerde hiç resim ve heykel yoktur, piskopos bulunmaz, papazlar ile seçilmiş ihtiyarlardan oluşan bir kurul yurttaşların ahlakını denetler ve kader öğretisi vaaz edilir. Bu kentin dinî düzeni en çok hangi geleneğe uyar?', 'Kalvinist', ['Lutherci', 'Katolik', 'Anglikan'], 'İmgesiz kiliseler, piskoposluğun reddi, ihtiyarlar kurulu ve kader öğretisi Cenevre modelinin temel unsurlarıdır.'),
  ('Lutherci bir prensin kendi topraklarındaki manastırları kapatıp mallarını devlete aktarması ile VIII. Henry\'nin İngiltere\'deki uygulaması karşılaştırıldığında ortak nokta hangisidir?', 'Kilise servetinin dünyevi yöneticinin denetimine geçmesi', ['Manastır mallarının papaya geri verilmesi', 'Keşişlerin yeni manastırlara yerleştirilip korunması ve maaş bağlanması', 'Kilise topraklarının köylülere ücretsiz dağıtılması'], 'Her iki örnekte de Reform, hükümdarların kilise mülkünü ele geçirmesine ve kilise üzerinde doğrudan otorite kurmasına fırsat verdi.'),
  ('1520\'lerde Anversli bir tüccar, satın aldığı biberin artık Venedik üzerinden değil Lizbon\'dan gelen gemilerle ulaştığını görüyor. Bu değişikliğin nedeni hangisidir?', 'Ümit Burnu üzerinden açılan deniz yolu', ['Venedik\'in Osmanlı\'ya katılarak bütün limanlarını kapatması ve ticareti durdurması', 'Biberin Portekiz\'de yetiştirilmeye başlanması ve iç pazarda bollaşması', 'Akdeniz\'in bir deprem sonucu ticarete kapanması ve gemilerin geçememesi'], 'Portekiz, baharatı Hint Okyanusu\'ndan doğrudan Lizbon\'a getirerek Anvers üzerinden Kuzey Avrupa\'ya dağıttı.'),
  ('Bir devlet aşırı güçlenerek kıtada üstünlük kurma eğilimi gösterdiğinde diğer devletlerin ona karşı ittifak kurması, erken modern diplomasinin hangi ilkesine örnektir?', 'Güç dengesi', ['Mezhep birliği ve din kardeşliği ilkesi', 'Hanedan evliliklerinin kutsallığı ilkesi', 'Papalığın hakemliği ve aforoz yetkisi'], 'XIV. Louis\'ye karşı kurulan Augsburg Birliği ve Büyük İttifak bu ilkenin örnekleridir; 1713 barışlarıyla açık bir diplomatik amaç hâline geldi.'),
  ('Keşif çağında yapılan uzun okyanus yolculuklarının başarısı için aşağıdaki gelişmelerden hangisi en az gerekliydi?', 'Buhar gücüyle çalışan gemi makineleri', ['Rüzgâra karşı da seyredebilen gemiler', 'Enlem ölçmeye yarayan aletler', 'Okyanus rüzgârları hakkında biriken bilgi'], 'Buhar makinesi 18. ve 19. yüzyılın ürünüdür; keşif gemileri tümüyle yelkenle seyretti.'),
  ('Otuz Yıl Savaşları sırasında paralı orduların sivillerden zorla erzak ve para toplaması, savaşın hangi özelliğini açıklar?', 'Savaşın halk üzerinde ağır bir yıkıma yol açmasını', ['Savaşın yalnız savaş alanlarında kalıp kentleri hiç etkilememesini', 'Askerlerin bütün masraflarını devletlerin düzenli maaşla karşılamasını', 'Savaşın kısa sürede ve az kayıpla bitmesini'], 'Ordular \'katkı\' adı verilen zorunlu ödemeler ve yağmayla beslendi; köyler boşaldı, salgın ve kıtlık yayıldı.'),
];
